quests[13320] = { id = 13320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann nicht reproduziert werden", description = "Ich kann ihre Kessel von hier aus riechen, doch was sie da zusammenbrauen, ist keine Seuche.\n\nDiejenigen, die dem Kult die Treue schwören, werden dazu gezwungen, ein Gemisch zu trinken, das ihren Willen raubt und sie für immer zu Sklaven des Lichkönigs macht.\n\nManche sagen, dass der Trank die verzerrte Seele eines Wesens beinhaltet, das gefoltert und schließlich gnadenlos getötet wurde, doch ich habe es noch nie geschafft, ihn zu reproduzieren...\n\nFüllt dieses Fläschchen mit Proben aus jedem der drei Kessel in der nordwestlichen Region des Tors auf und bringt sie zu Chefingenieur Bolzenschlüssel.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr das unterteilte Fläschchen an jedem der 3 Kessel der Kultisten auffüllt und es anschließend zu Chefingenieur Bolzenschlüssel bringt.", progress = "Was habt Ihr da, {race}?", completion = "<Bolzenschlüssel schüttet den Inhalt des Fläschchens in seinen Tetrahydropartikelanalysierer.>\n\nWas wir hier sehen, ist nichts weiter, als dass diese Flüssigkeit kein Gemisch bilden kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[13321] = { id = 13321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt neu testen", description = "Das sollte seinen Zweck erfüllen!\n\nDiese verdrehten Hooligans suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Der einzige Effekt wird sein, dass Ihr die Essenz der Kultisten werdet aufspüren können, sobald Ihr sie besiegt habt.\n\nSobald Ihr ein paar Essenzen habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", sourceObjective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur'thar werft.", completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13322] = { id = 13322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt neu testen", description = "Diese verdrehten Kultisten suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Ich bin mir fast sicher, dass Ihr als Effekt die Essenzen der Kultisten aufspüren könnt.\n\nSobald Ihr ein paar davon habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", sourceObjective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr das verdünnte Kulttonikum trinkt, Kultisten in Aldur'thar tötet und ihnen ihre besudelte Essenz abnehmt. Fügt danach 10 von den Essenzen zu einer windenden Masse zusammen und werft diese dann in einen ihrer Kessel.", completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13323] = { id = 13323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Gewandung", description = "Es sieht aus, als würde die Zahl der Initianden wieder wachsen. Ihr wisst, was Ihr zu tun habt...\n\nDie neuen Kultisten werden am südlichen Ende des Tores eingewiesen. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr einige davon habt, dann wendet sie auf die Unterwerfer dort an.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", sourceObjectiveStatus = "unverified-source-field" }
quests[13324] = { id = 13324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prismenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Prismenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Prismenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Prismenkartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Prismenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13325] = { id = 13325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaoskartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Chaoskartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Chaoskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Chaoskartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Chaoskartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13326] = { id = 13326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adligenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Adligenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Adligenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Adligenkartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Adligenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13327] = { id = 13327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untodeskartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Untotenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Untotenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Untotenkartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Untotenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13328] = { id = 13328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Scherbenhaufen hinterlassen", description = "Oberhalb der Schlachtfelder von Corp'rethar haben die Günstlinge des Lichkönigs drei Kristalle aufgestellt, die Splitter des Schreckens, der Verzweiflung und des Leidens. Sollte es unseren Männern gelingen, die Mauern von Corp'rethar zu erreichen, so wird er diese Waffen gegen unsere Armee einsetzen.\n\nVoll zum Einsatz gebracht, werden diese Kristalle den Geist unserer Männer peinigen und sie mit Schmerz und Angst lähmen. Dann wird es der Geißel ein Leichtes sein, sie einfach so niederzumetzeln.\n\nFindet diese Splitter, zerstört sie und bringt mir ihre zerbrochenen Überreste. Wir dürfen nicht zulassen, dass der Lichkönig diese Waffen einsetzt!", sourceObjective = "Bringt Koltira Todesweber an Bord der Orgrims Hammer den zerbrochenen Splitter des Schreckens, den zerbrochenen Splitter der Verzweiflung und den zerbrochenen Splitter des Leidens.", progress = "Habt Ihr die neuen Waffen des Lichkönigs zerstört?", completion = "<Koltira nimmt die Kristallsplitter entgegen und spricht mit ruhiger Stimme.>\n\nIch erinnere mich hieran...\n\nSchwächere Männer würden leicht unter ihrem Angriff zusammenbrechen. Diese Bedrohung zu beenden war gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13329] = { id = 13329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor dem Tor des Schreckens", description = "Der Großbrand, das Gebiet vor Corp'rethar südlich des Eisenwallbollwerks, ist der Ort, an dem sich die Elitesoldaten des Lichkönigs zur Verteidigung der Zitadelle formiert haben.\n\nDer Weg wird von einer Legion Skeletthäscher versperrt, angeführt von einem Todesritterkontingent. Ich befürchte, dass, selbst wenn die Häscher beseitigt werden sollten, die Geißel sie einfach wieder aufstellen und gegen uns in den Kampf schicken würde.\n\nIch habe zwar einen Plan entwickelt, wie wir sie davon abhalten können, bin mir jedoch nicht sicher, ob es funktionieren wird. Hier, nehmt diese Lösung und zersetzt mit ihr die Überreste der Häscher.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer wünscht, dass Ihr mithilfe der flüchtigen Säure die Überreste von 6 Skeletthäschern zersetzt.", completion = "<Koltira hört sich Euren Bericht an.>\n\nGut. Ich werde die Ingenieure so viel wie möglich von der Säure zusammenmischen lassen, bevor wir Corp'rethar mit der Hauptstreitmacht angreifen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13330] = { id = 13330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut der Auserwählten", description = "Diejenigen Vrykul, die beim Lichkönig hoch im Ansehen stehen, nennen sich selbst die Ymirjar. Sie bewohnen eine Stadt im Zentrum von Eiskrone. Wir haben eine Menge Aufgaben zu erledigen, bevor wir die Eiskronenzitadelle angreifen können, und diejenige, die uns nun bevorsteht, ist, diese so genannten \"Auserwählten\" des Lichkönigs plattzumachen.\n\nBegebt Euch in Ihre Stadt, Ymirheim, und schlachtet sie in ihren Häusern ab. Hinterlasst keine Zweifel darüber, wer hier die stärkeren Kämpfer hat.", sourceObjective = "Kriegshetzer Davos Rabatz auf der Orgrims Hammer hat Euch entsandt, 20 Vrykul in Ymirheim zu töten.", completion = "Wohl doch nicht ganz so stark, wie? Der Lichkönig erntet nun, was er gesät hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13331] = { id = 13331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Allianz die Augen zuhalten", description = "Die Allianz ist hartnäckig, so viel gestehe ich ihr zu, aber es bedarf mehr, um uns aufzuhalten. Nehmt diese BGR-3 und schießt erneut die Kampfaufklärer der Himmelsbrecher ab.\n\nIch bezweifele zwar, dass die Nachricht in ihre dicken Schädel reingeht, aber wir verfügen über genügend Raketen, um unseren Punkt deutlich zu machen. Geht und haltet über dem Tal der gefallenen Helden, westlich von Aldur'thar, nach ihren Aufklärern Ausschau. Und kommt nicht zurück, solange Ihr sie nicht in Trümmer gelegt habt.", sourceObjective = "Benutzt die BGR-3 um 6 Kampfaufklärer der Himmelsbrecher zu zerstören und erstattet dann dem Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer Bericht.", completion = "Mal wieder gut gemacht. Die Vorherrschaft der Horde ist gesichert, jedenfalls bis dieser Allianzlerabschaum sich entschließt, uns erneut herauszufordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13332] = { id = 13332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errichtet die Barrikaden", description = "Sobald unsere Truppen sich hinter Aldur'thar befinden, werden sie verwundbar durch Attacken vom Eisenwallbollwerk oder dem breiten Gletscher darunter sein.\n\nWir haben weder die Zeit noch das Material, um Befestigungen zu bauen, aber wir können ein paar Barrikaden errichten, um unsere Männer vor Feuer zu schützen und Angriffe der Geißel abprallen zu lassen.\n\nNehmt diesen Barrikadenbausatz mit zum Tal der Gefallenen Helden. Findet die Markierungen, die ich dort gesetzt habe und benutzt den Bausatz, um dort Eure Barrikaden zu errichten.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 8 Barrikaden mithilfe Eures Barrikadenbausatzes errichtet.", completion = "<Thassarian nickt kurz.>\n\nGut. Sie bieten nicht gerade viel Schutz, aber immer noch besser als nichts. Dieses Tor ist noch immer der perfekte Engpass, wenn die Geißelanführer wissen, was sie tun. Wir müssen so viel von dem umliegenden Gebiet wie möglich einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13333] = { id = 13333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Sendungen abfangen", description = "Trotz unserer Anstrengungen schickt die Horde weiterhin Späher in diese Gegend des Eiskronengletschers, westlich des Eisenwallbollwerks und Aldur'thar.\n\nWir können es uns nicht leisten, der Horde bei dieser Erkundungsoperation die Oberhand zu lassen. Nehmt wieder diese Pfeilpistole mit Euch und zeigt den Spähern der Orgrims Hammer keine Gnade! Bringt die abgefangenen Sendungen zu mir.\n\nWir werden die Fehlschläge der Horde zu unseren Gunsten nutzen.", sourceObjective = "Fangt 6 Sendungen der Orgrims Hammer von den Spähern der Orgrims Hammer ab und bringt sie zu Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher.", progress = "Habt Ihr die Sendungen abgefangen?", completion = "<Der Hochkapitän nimmt die Sendungen entgegen.>\n\nDas ist genau, was wir brauchen. Selbst die Horde ist nicht so dumm, einen Ansturm auf die Geißel blind zu wagen. Mit ihren Berichten in Händen, werden wir gut vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13334] = { id = 13334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutbespritzte Banner", description = "Im Tal der gefallenen Helden und am Eiskronengletscher, im Westen Aldur'thars, versucht die Geißel, die Gefallenen gegen uns zu verwenden. Die Kommandanten der Geißel haben die Toten aus dem Tal wiedererweckt und sie mit furchterregender Stärke und Leidenschaft erfüllt. Die Banner, die die Geißelanführer in der Gletschergegend bei sich tragen, sind die Quelle dieser Mächte. Tötet die Bannerträger und Ihr werdet die konvertierten Helden, die sie führen, schwächen.\n\nEs obliegt Euch, uns von diesem Hindernis zu befreien und zu testen, wie es um deren Widerstand steht, bevor die Hauptstreitmacht vorrücken kann.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr 5 Bannerträger der Geißel, 5 Konvertierer der Geißel und 20 konvertierte Helden tötet.", completion = "Ihr habt die Bannerträger der Geißel und ihre Lakaien entfernt? Gut. Unsere Vorbereitungen müssen weitergehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13335] = { id = 13335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor dem Tor des Schreckens", description = "Der Großbrand, das Gebiet vor Corp'rethar südlich des Eisenwallbollwerks, ist der Ort, an dem sich die Elitesoldaten des Lichkönigs zur Verteidigung der Zitadelle formiert haben.\n\nDer Weg wird von einer Legion Skeletthäscher versperrt, angeführt von einem Todesritterkontingent. Ich befürchte, dass, selbst wenn die Häscher beseitigt werden sollten, die Geißel sie einfach wieder aufstellen und gegen uns in den Kampf schicken würde.\n\nIch habe zwar einen Plan entwickelt, wie wir sie davon abhalten können, bin mir jedoch nicht sicher, ob es funktionieren wird. Hier, nehmt diese Lösung und zersetzt mit ihr die Überreste der Häscher.", sourceObjective = "Thassarian an Bord der Himmelsbrecher wünscht, dass Ihr mithilfe der flüchtigen Säure die Überreste von 6 Skeletthäschern zersetzt.", completion = "<Thassarian hört Euch zu, als Ihr von Eurem erfolgreichen Test erzählt.>\n\nDie Säure hat also funktioniert? Gut. Wir werden sie brauchen, wenn die Armee die Häscher mit voller Stärke angreifen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13336] = { id = 13336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut der Auserwählten", description = "Diejenigen Vrykul, die beim Lichkönig hoch im Ansehen stehen, nennen sich selbst die Ymirjar. Sie bewohnen eine Stadt im Zentrum von Eiskrone. Wir haben eine Menge Aufgaben zu erledigen, bevor wir die Eiskronenzitadelle angreifen können, und diejenige, die uns nun bevorsteht, ist, diese so genannten \"Auserwählten\" des Lichkönigs plattzumachen.\n\nBegebt Euch in Ihre Stadt, Ymirheim, und schlachtet sie in ihren Häusern ab. Hinterlasst keine Zweifel darüber, wer hier die stärkeren Kämpfer hat.", sourceObjective = "Kürassier Drosche auf der Himmelsbrecher hat Euch entsandt, 20 Vrykul in Ymirheim zu töten.", completion = "Der Verräterkönig wird gestürzt werden. Daran hege ich keinen Zweifel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13337] = { id = 13337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eisenwallbollwerk", description = "Das Eisenwallbollwerk blickt über das Tal der Gefallenen Helden westlich von Aldur'thar. Vom Bollwerk aus kann man die Felder zu allen Seiten hin kontrollieren. Wir werden nicht weiter vorstoßen können, wenn das Bollwerk nicht genommen werden kann - doch es wird von Grimkor dem Boshaften und seinen Jüngern des Kults der Verdammten gehalten.\n\nWenn Ihr Grimkor schwächen könnt, werden unsere Streitkräfte wissen, was sie bei ihrem Vormarsch erwarten wird. Hier, nehmt diese Rune der Verzerrung. Seine Macht in der Nähe von Grimkors Kugel am Ende des Bollwerks freizusetzen, sollte genügen, um die Aufmerksamkeit der Nekromanten zu erregen.", sourceObjective = "Besiegt Grimkor den Boshaften und kehrt zu Thassarian an Bord der Himmelsbrecher zurück.", progress = "Habt Ihr Eure Mission abgeschlossen?", completion = "Grimkor ist also durch Eure Hand gefallen? Ausgezeichnete Arbeit. Mit ihm aus dem Weg sind unsere Chancen, das Bollwerk während des Angriffs zu halten, um einiges größer.", sourceObjectiveStatus = "unverified-source-field" }
quests[13338] = { id = 13338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter von Corp'rethar", description = "Corp'rethar, das Tor des Schreckens, ist das letzte Hindernis zwischen uns und der Eiskronenzitadelle. Es befindet sich südlich des Eisenwallbollwerks jenseits des Gletschers und des Großbrands. Wenn unsere Truppen erst einmal dort angekommen sind, werden sie erschöpft sein, falls ihnen nicht schon Schlimmeres zugestoßen ist.\n\nWir müssen seine Verteidigung schwächen, oder unsere Armee wird an seinen Mauern zugrunde gehen.\n\nDie Zinnen werden von einigen der stärksten und eifrigsten Dienern des Lichkönigs bemannt. Tut alles, was in Eurer Macht steht, um diese Wächter zu vernichten, und hofft, dass dies ausreicht.", sourceObjective = "Thassarian an Bord der Himmelsbrecher wünscht, dass Ihr 5 Herolde des Schreckens und 5 Wächter von Corp'rethar tötet.", completion = "Ich hoffe, dass sich Euer Erfolg bei Corp'rethar als Omen für die kommende Schlacht erweisen wird. Der Lichkönig kann nicht tatenlos herumstehen, während wir auf die Tore seiner Festung zumarschieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13339] = { id = 13339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Scherbenhaufen hinterlassen", description = "Oberhalb der Schlachtfelder von Corp'rethar haben die Günstlinge des Lichkönigs drei Kristalle aufgestellt, die Splitter des Schreckens, der Verzweiflung und des Leidens. Sollte es unseren Männern gelingen, die Mauern von Corp'rethar zu erreichen, so wird er diese Waffen gegen unsere Armee einsetzen.\n\nVoll zum Einsatz gebracht, werden diese Kristalle den Geist unserer Männer peinigen und sie mit Schmerz und Angst lähmen. Dann wird es der Geißel ein Leichtes sein, sie einfach so niederzumetzeln.\n\nFindet diese Splitter, zerstört sie und bringt mir ihre zerbrochenen Überreste. Wir dürfen nicht zulassen, dass der Lichkönig diese Waffen einsetzt!", sourceObjective = "Bringt Thassarian an Bord der Himmelsbrecher den zerbrochenen Splitter des Schreckens, den zerbrochenen Splitter der Verzweiflung und den zerbrochenen Splitter des Leidens.", progress = "Habt Ihr die neuen Waffen des Lichkönigs zerstört?", completion = "<Thassarian nimmt die Kristallsplitter entgegen und spricht mit ruhiger Stimme.>\n\nIch erinnere mich hieran...\n\nSchwächere Männer würden leicht unter ihrem Angriff zusammenbrechen. Diese Bedrohung zu beenden war gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13340] = { id = 13340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt Euch dem Angriff an", description = "Wir brauchen mehr Leute, die sich dem Hauptangriff auf Ymirheim anschließen.\n\nJeder Krieger mit einer halben Gehirnzelle kann Euch sagen, dass die Vrykul grimmige Krieger sind, die man nicht auf die leichte Schulter nehmen sollte. Das gilt erst recht für die Ymirjar. Sie haben uns bereits spüren lassen, warum der Lichkönig sie für würdig befunden hat.\n\nFeldkommandant Xutjja befehligt den Angriff. Die Stadt selber befindet sich im Zentrum von Eiskrone, und Xutjjas Truppen sind nahe der Kante des Gletschers im Norden der Stadt positioniert.", sourceObjective = "Meldet Euch bei Feldkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim.", completion = "Mehr Fleisch für den Schleifer. Willkommen in der Hölle, Soldat.\n\nMeine Männer werden den Angriff auf das Tor von hier aus beginnen, und wir werden einige Infiltratoren aus der Luft absetzen. Wir brauchen mehr Leute an beiden Fronten. Ich habe so das Gefühl, dass sich dieser Angriff eine ganze Weile ziehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13341] = { id = 13341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt Euch dem Angriff an", description = "Wir brauchen mehr Leute, die sich dem Hauptangriff auf Ymirheim anschließen.\n\nJeder Krieger mit einer halben Gehirnzelle kann Euch sagen, dass die Vrykul grimmige Krieger sind, die man nicht auf die leichte Schulter nehmen sollte. Das gilt erst recht für die Ymirjar. Sie haben uns bereits spüren lassen, warum der Lichkönig sie für würdig befunden hat.\n\nFeldkommandant Koup befehligt den Angriff. Die Stadt selber befindet sich im Zentrum von Eiskrone, und Koups Truppen sind nahe der Kante des Gletschers im Osten der Stadt positioniert.", sourceObjective = "Meldet Euch bei Feldkommandant Koup an der Kante des Gletschers im Osten von Ymirheim.", completion = "Willkommen in der Hölle, Soldat.\n\nMeine Männer werden den Angriff auf das Tor von hier aus beginnen, und wir werden einige Infiltratoren aus der Luft absetzen. Wir brauchen mehr Leute an beiden Fronten. Ich habe so das Gefühl, dass sich dieser Angriff eine ganze Weile ziehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13342] = { id = 13342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Wanze", description = "So, <mein Freund/meine Freundin>, es ist an der Zeit eine Wanze zu platzieren.\n\nBeruhigt Euch, es ist nicht wirklich eine Wanze, aber es wird unseren Zwecken dienlich sein.\n\nIm nördlichen Bereich von Aldur'thar versklaven die Leerenbeschwörer des Kults dämonische Lakaien. Benutzt diese Rute, um den Körpern dieser versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um unseren kleinen Spion zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", completion = "Das habt Ihr gut gemacht, {class}.\n\nDer Bote hat uns bereits einige wertvolle Informationen zukommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13343] = { id = 13343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnis der Ewigen, die 2.", description = "Da seid Ihr ja! Oder haben wir gerade erst miteinander gesprochen?\n\n<Chromie denkt über die Vielfalt der temporalen Möglichkeiten nach.>\n\nWie dem auch sei, die Ewigen sind hinter Euch her! Nun, an und für sich sind sie nicht hinter Euch her, sondern eher hinter der vergangenen Version von Euch, die einst das Stundenglas der Ewigkeit verteidigte. Ihr könnt Euch noch daran erinnern, oder?\n\nIhr wart das damals, nur seid Ihr es jetzt auch wieder. Halt, das ist nicht so wichtig. Was wichtig ist, ist, dass Ihr zurück zum Bronzedrachenschrein geht und Euch und das Stundenglas vor ihren Angriffen schützt, bevor man Euch aus der Geschichte entfernt!", sourceObjective = "Chromie auf der höchsten Ebene des Wyrmruhtempels wünscht, dass Ihr noch einmal zum Bronzedrachenschrein reist.\n\nSobald Ihr dort seid, sollt Ihr das Stundenglas der Ewigkeit auf den Boden stellen und Eurem vergangenen Selbst dabei helfen, es vor den Truppen des ewigen Drachenschwarms zu beschützen.", completion = "Ach du meine Güte, Ihr habt es geschafft! Ich war mir nicht sicher, ob es Euch gelingen würde.\n\nIhr seid während des Kampfes für einen Moment aus dem Zeitfluss verschwunden! Ich habe schon gedacht, wir hätten Euch verloren!\n\nDoch da seid Ihr gesund und munter - Euer vergangenes Selbst auf der anderen Seite der Zeitschleife, in der Ihr feststecktet, gerettet.\n\nIhr seid ein ziemlich temporaler Held, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13344] = { id = 13344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Wanze", description = "Die Kultisten haben den letzten Boten, den Ihr beschworen habt, entdeckt, {race}.\n\nEr hat uns zwar bereits sehr viele Informationen beschafft, aber es ist wichtig, dass wir weiter über jeden Schritt unserer Feinde informiert sind.\n\nBenutzt diese Rute, um den Körpern der versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um einen weiteren dunklen Boten zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", completion = "Gut gemacht, Freund.\n\nDer Bote ist bereits bei der Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13345] = { id = 13345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauche mehr Informationen", description = "Der Kult der Verdammten ist dafür berühmt, grandiose Pläne auszuarbeiten, die letzten Endes allerdings selten erfolgreich sind. Diesmal allerdings scheint es anders zu sein...\n\nVielleicht ist es die Nähe zum Lichkönig, die ihre Inbrunst angefacht hat. Was immer es auch ist, sie scheinen selbstbewusster denn je. Wir müssen herausfinden, was ihren Eifer befeuert und dieses dann ganz schnell unterbinden!\n\nIch glaube, dass der Schlüssel dazu ihre Forscher sind. Findet heraus, was sie im Schilde führen und berichtet mir dann.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 3 Seiten Forschung der Kultisten von den Forschern der Kultisten in Aldur'thar sammelt, um damit eine These über den Kult der Verdammten zu erstellen.", progress = "Habt Ihr herausgefunden, was die Forscher im Schilde führen, {class}?", completion = "Das ist in der Tat alarmierend...", sourceObjectiveStatus = "unverified-source-field" }
quests[13346] = { id = 13346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann der Böseste nicht in Frieden ruhen...", description = "Die Dummköpfe sind übrigens über etwas gestolpert, das äußerst gefährlich für unsere Pläne werden könnte!\n\nAlumeth, der Anführer dieser Sekte, hat sich in einem Ritual selbst geopfert und nun versorgen seine Untergebenen seine Seele mit Macht.\n\nWenn wir ihn weiterhin in Ruhe lassen, werden sie ihn schon bald zu einem mächtigen Gegner machen.\n\nIn ihrer Kammer verteilt liegt sein Herz, Szepter, Schädel und seine Robe - kombiniert sie miteinander und benutzt das, was dabei rauskommt, in der Nähe der dortigen Kristalle.\n\nBeeilt Euch, {race}! Vernichtet ihn, bevor er noch mächtiger wird!", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar besiegt.", completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", sourceObjectiveStatus = "unverified-source-field" }
quests[13347] = { id = 13347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergeboren aus der Asche", description = "Unser Schicksal steht schon von Geburt an fest. Bolvars Fall, wenn auch tragisch, war unvermeidlich.\n\nAlles, was Ihr jetzt noch tun könnt, {name}, ist, Eurem Helden die letzte Ehre zu erweisen. Geht zum Schlachtfeld, holt Euch Bolvars Schild und bringt ihn Eurem König. Übermittelt ihm bei der Übergabe diese Botschaft: \"Nicht alles ist verloren. Aus der Asche der Gefallenen wird eine Macht emporsteigen, die Reiche vereinen und das Böse aus dieser Welt treiben wird.\"\n\nEr darf den Glauben nicht verlieren. Geht jetzt, {name}. Euer Volk braucht einen Helden - es braucht Euch.", sourceObjective = "Geht zum Schlachtfeld vor Angrathar, der Pforte des Zorns, findet Fordragons Schild und bringt ihn zu König Varian Wrynn nach Burg Sturmwind in Sturmwind.", progress = "<König Wrynn wischt sich eine Träne aus dem Gesicht.>\n\n<Er nickt.>\n\nDas ist meine Schuld.", completion = "Die Drachenkönigin hat recht, {name}. Noch ist nicht alles verloren. Ich werde die Macht sein, die aus der Asche steigt, und ich werde das Böse der Horde aus der Welt schaffen. Der Tod unserer Brüder und Schwestern wird nicht umsonst gewesen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13348] = { id = 13348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinnlosigkeit", description = "Seht Ihr es nun? Eure Männer gegen die Armeen des Prinzen zu entsenden sorgt nur dafür, dass ihre Reihen weiter anwachsen.\n\nIch erwarte nicht, dass Ihr es versteht... Ihr werdet vermutlich auch wie die anderen enden. Am besten kehrt Ihr zu denjenigen zurück, die Euch entsandt haben. Sie werden sich Sorgen machen.", sourceObjective = "Kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.", completion = "Da seid Ihr ja. Gute Arbeit unten im Tal. Das Gemetzel konnte man selbst von hier oben aus verfolgen.\n\nSeid Ihr in Ordnung? Ihr seht aus, als hättet Ihr einen Geist gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13349] = { id = 13349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiege der Frostbrut", description = "Wir müssen unseren Vorteil ausnutzen und weitermachen. Lasst uns den Streitkräften der Geißel keine Pause gönnen.\n\nSindragosas Sturz liegt gleich östlich jenseits des Tals der Verlorenen Hoffnung. Der Kult der Verdammten operiert dort unter strenger Aufsicht der untoten Vrykullakaien des Lichkönigs.\n\nEs ist ein Ort großer Macht, möglicherweise ein Friedhof des blauen Drachenschwarms, in dem sie aus den Knochen blauer Drachen die gefürchtete Frostbrut geschaffen.\n\nEin Angriff dort würde es für den Feind erheblich schwieriger machen, an Frostwyrm heranzukommen. Was sagt Ihr dazu, {name}?", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Wyrmwiedererwecker, 8 Verderber der Kultisten und 3 Nekrolords der Vrykul in Sindragosas Sturz tötet.", completion = "Das habt Ihr gut gemacht, {name}. Ihr ruht Euch besser für eine Weile aus. Ihr seht ein wenig blass aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13350] = { id = 13350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann der Böseste nicht in Frieden ruhen...", description = "Es ist Alumeth... Seine Macht wächst wieder an. Ich kann es fühlen. Wieder versorgen seine Untergebenen seine Seele mit Energie.\n\nWenn wir zulassen, dass er sich weiter erholt, werden ihre Bemühungen ihn zu einem mächtigen Gegner machen.\n\nKehrt in seine Kammer im Norden von Aldur'thar zurück. Sammelt sein Herz, seinen Schädel, sein Zepter und seine Kleider und wendet seine Überreste dann auf den Kristall dort an.\n\nEilt Euch, {race}! Vernichtet ihn, bevor er noch mächtiger wird!", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar vernichtet.", completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", sourceObjectiveStatus = "unverified-source-field" }
quests[13351] = { id = 13351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorschau", description = "Wir machen Fortschritte. Uns steht eine vielversprechende Reihe von Taktiken zur Verfügung, die uns die Kontrolle über das Tor des Todes verschaffen sollten. Es wird zweifellos viele Verluste geben, doch am Ende sollten wir die Oberhand gewinnen - außer, die Allianz mischt sich ein.\n\nAls Nächstes werden wir uns auf Aldur'thar, das Tor der Verwüstung, konzentrieren. Fliegt hinunter und macht Euch mit der Konstruktion und den dort postierten Feinden vertraut.\n\nWenn Ihr wieder zurück seid, werde ich Eure Einsatzbeschreibungen vorbereitet haben.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr hinunter zum Tor der Verwüstung fliegt und Euch den südlichen, zentralen, nördlichen und nordwestlichen Bereich des Tors anseht.", completion = "Schön und gut, {class}.\n\nNun, da Ihr mit eigenen Augen gesehen habt, wem wir hier gegenüberstehen, ist es Zeit, an die Arbeit zu gehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13352] = { id = 13352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Gewandung", description = "Der Kult der Verdammten hält das Tor der Verwüstung, wie? Wundert mich nicht.\n\nZeit, ein wenig Spaß zu haben. Ihr habt erwähnt, dass am südlichen Ende des Tores neue Kultisten ausgebildet werden. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr eine von den Kugeln gefunden habt, {class}, und wendet sie dann auf einen Unterwerfer an.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", sourceObjectiveStatus = "unverified-source-field" }
quests[13353] = { id = 13353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Gewandung", description = "Es sieht aus, als würde die Zahl der Initianden wieder wachsen. Ihr wisst, was Ihr zu tun habt...\n\nDie neuen Kultisten werden am südlichen Ende des Tores eingewiesen. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr einige davon habt, dann wendet sie auf die Unterwerfer dort an.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", sourceObjectiveStatus = "unverified-source-field" }
quests[13354] = { id = 13354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlskette", description = "Eurem Bericht und meinem Wissen über den Kult nach lassen sie einen Aufseher die Operation in jedem Lager am Tor leiten.\n\nIhre Anführer auszuschalten, wäre zwar nur ein vorübergehender Rückschlag für sie, doch es wird sie zumindest verlangsamen und aus dem Gleichgewicht bringen. Und das, {race}, ist für den Augenblick gut genug.\n\nSucht nach diesen Aufsehern und kommt wieder zu mir zurück, wenn sie beseitigt wurden.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr nach Aldur'thar geht und Aufseher Faedris, Aufseher Savryn, Aufseher Veraj und Aufseher Jhaeqon besiegt.", completion = "Gut gemacht, {race}. Doch brecht Euch beim \"Auf die Schulter klopfen\" nicht den Arm. Sie werden diese Aufseher im Nu ersetzt haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[13355] = { id = 13355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann nicht reproduziert werden", description = "Ich kann ihre Kessel von hier aus riechen, doch was sie da zusammenbrauen, ist keine Seuche.\n\nDiejenigen, die dem Kult die Treue schwören, werden dazu gezwungen, ein Gemisch zu trinken, das ihren Willen raubt und sie für immer zu Sklaven des Lichkönigs macht.\n\nManche sagen, dass der Trank die verzerrte Seele eines Wesens beinhaltet, das gefoltert und schließlich gnadenlos getötet wurde, doch ich habe es noch nie geschafft, ihn zu reproduzieren...\n\nFüllt dieses Fläschchen mit Proben aus jedem der drei Kessel in der nordwestlichen Region des Tors auf und bringt sie zu Chefingenieur Kupferklammer.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr das unterteilte Fläschchen an jedem der 3 Kessel der Kultisten auffüllt und es anschließend zu Chefingenieur Kupferklammer bringt.", progress = "Was habt Ihr da, {race}?", completion = "<Kupferklammer schüttet den Inhalt des Fläschchens in seinen Partikelanalysierer.>\n\nAhh... ich weiß genau das Richtige!", sourceObjectiveStatus = "unverified-source-field" }
quests[13356] = { id = 13356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt neu testen", description = "Das sollte seinen Zweck erfüllen!\n\nDiese verdrehten Hooligans suchen nach Seelen, die sie in ihren Irren-Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Der einzige Effekt wird sein, dass Ihr die Essenz der Kultisten werdet aufspüren können, sobald Ihr sie besiegt habt.\n\nSobald Ihr ein paar Essenzen habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", sourceObjective = "Chefingenieur Kupferklammer an Bord der Orgrims Hammer möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur'thar werft.", completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13357] = { id = 13357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt neu testen", description = "Diese verdrehten Kultisten suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Ich bin mir fast sicher, dass Ihr als Effekt die Essenzen der Kultisten aufspüren könnt.\n\nSobald Ihr ein paar davon habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", sourceObjective = "Chefingenieur Kupferklammer an Bord der Orgrims Hammer möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur'thar werft.", completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13358] = { id = 13358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Wanze", description = "So, <mein Freund/meine Freundin>, es ist an der Zeit eine Wanze zu platzieren.\n\nBeruhigt Euch, es ist nicht wirklich eine Wanze, aber es wird unseren Zwecken dienlich sein.\n\nIm nördlichen Bereich von Aldur'thar versklaven die Leerenbeschwörer des Kults dämonische Lakaien. Benutzt diese Rute, um den Körpern dieser versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt den Beschwörungskristall der Kultisten, um unseren kleinen Spion zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", completion = "Das habt Ihr gut gemacht, {class}.\n\nDer Bote hat uns bereits einige wertvolle Informationen zukommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13359] = { id = 13359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Drachen einst fielen", description = "Einst fiel hier eine ganze Brut von blauen Drachen. Und nun wird jeder einzelne von ihnen von seinen Dienern wiedererweckt.\n\nDen größten von ihnen hat er selbst wiedererweckt. Bringt mir ein wenig Knochenstaub von ihren Welpen und ich werde Euch ganz genau zeigen, wie er das gemacht hat.", sourceObjective = "Matthias Lehner in Sindragosas Sturz möchte, dass Ihr 6 Einheiten Welpenknochenstaub besorgt.", progress = "Habt Ihr den Staub bekommen, {name}?", completion = "Selbst die mächtigen Wyrm mussten seinem Ruf folgen. Wie könnte ein einfacher Sterblicher wie Ihr ihm widerstehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13360] = { id = 13360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Antworten", description = "Ihr habt viele Fragen, {name}. Ihr seid <der Einzige, der/die Einzige> die; mich sehen kann, weil Ihr etwas berührt habt, das einst ihm gehörte... könnt Ihr Euch nicht mehr erinnern?\n\nIhr wisst nicht, was es ist? Nun, ich kann es Euch nicht einfach so sagen... das würde ihn ziemlich wütend machen. Er ist nicht mehr bloß ein Prinz... er ist jetzt der König!\n\nTrefft mich im Hof der Knochen nördlich der Eiskronenzitadelle und Ihr könnt es für Euch selbst sehen.", sourceObjective = "Sprecht mit Matthias Lehner im Hof der Knochen.", completion = "Da seid Ihr ja. Ich habe mich schon gefragt, wann Ihr auftauchen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13361] = { id = 13361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jäger und der Prinz", description = "Bevor der Prinz König wurde, schlug er viele Schlachten... doch nur bei einer wäre er beinahe gestorben.\n\nSie fand genau hier statt. Nachdem ich Euch gezeigt habe, was hier einst geschah, werdet Ihr verstehen.\n\nSucht nach einem blutbefleckten Stein und hebt ihn auf. Ihr werdet sehen, was einst geschah.", sourceObjective = "Matthias Lehner im Hof der Knochen möchte, dass Ihr nach einem blutbefleckten Stein sucht und das Schicksal des Prinzen zu Ende bringt.", progress = "Habt Ihr es gesehen, {name}? Habt Ihr es gesehen?", completion = "Nach dem Kampf erkannte der Prinz, dass das, was ihn zurückhielt, seine Menschlichkeit war... Er konnte noch immer fühlen... konnte noch immer bluten. Er hatte noch immer ein Herz.\n\nSeine erste Handlung als König war es, sein Herz loszuwerden. Er warf es die Grube hinunter, in der wir uns zum ersten Mal begegneten. Und Ihr, {name}, wart der Erste, der es seitdem berührt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13362] = { id = 13362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist eine schreckliche Bürde", description = "Jetzt wisst Ihr, womit Ihr es zu tun habt, {name}. Ein Gegner, der keinen Schmerz mehr kennt... keine Zweifel... und auch keine Menschlichkeit. Ein Gegner, der alles tun würde, um das zu bekommen, was er will.\n\nDas Herz war seine Schwachstelle und er weiß jetzt, dass Ihr es gefunden habt.\n\nWenn Ihr zurückwollt, um es zu holen, dann nehmt Euch besser Hilfe mit. Er wird es nicht noch einmal unbewacht lassen.", sourceObjective = "Meldet Euch bei Koltira Todesweber an Bord der Orgrims Hammer.", completion = "Der Geist eines kleinen Kindes... Das Herz Arthas'... langsam, langsam... In meinem Kopf dreht sich alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[13363] = { id = 13363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe vom Argentumkreuzzug", description = "Es gab Gerüchte unter den Todesrittern über die Ereignisse, von denen Ihr gesprochen habt. Ich hatte immer gedacht, dass sie etwas... symbolischer gemeint wären.\n\nWir müssen die anderen warnen, aber diskret. Sobald der Lichkönig von unserem Aufbruch erfährt, wird er das Herz an einen anderen Ort bringen lassen - solch eine Chance werden wir nie wieder bekommen.\n\nDie Horde und die Allianz wurden schon zuvor vom Kult der Verdammten infiltriert. Die Schwarze Klinge operiert zu nah an der Geißel.\n\nWir müssen mit Tirion Fordring und seinem Argentumkreuzzug sprechen.", sourceObjective = "Sprecht mit Hochlord Tirion Fordring im Kreuzfahrerturm.", completion = "Harte Worte, {name}. Hätte jemand anderes das gesagt, hätte ich ihn wahrscheinlich für verrückt erklärt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13364] = { id = 13364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirions Schachzug", description = "Diesen Morgen haben mich meine Späher darüber informiert, dass eine Prozession des Kults der Verdammten mit einem Artefakt von der Eiskronenzitadelle in Richtung Kathedrale der Dunkelheit aufgebrochen ist.\n\nUnd nun wird mir gesagt, dass es sich hierbei um Arthas' eigenes Herz handelt... ein Gegenstand, der den letzten Rest seiner Menschlichkeit enthält.\n\nDies ist ein Zeichen des Lichts. Solange solch ein Artefakt existiert, besteht eine Chance, dass Arthas Menethil wieder ein Mensch werden kann!\n\nTrefft mich am Eingang der Kathedrale. Bringt auf jeden Fall eine Kultistenverkleidung mit - wir gehen inkognito.", sourceObjective = "Tirion Fordring auf dem Kreuzfahrerturm möchte, dass Ihr die Kultistenkapuze besorgt, diese anzieht und Euch mit ihm am Eingang zur Kathedrale der Dunkelheit nordwestlich der Eiskronenzitadelle trefft.", completion = "Ich betrachte das, was wir soeben durchgemacht haben, nicht als Fehlschlag, {name}... im Gegenteil.\n\nDadurch, dass ich einen Blick in sein Herz werfen konnte, habt Ihr mir erlaubt, das zu bestätigen, was ich wissen musste. Es gibt keinen Arthas Menethil mehr - nur noch den Lichkönig.", sourceObjectiveStatus = "unverified-source-field" }
quests[13365] = { id = 13365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Wanze", description = "Die Kultisten haben den letzten Boten, den Ihr beschworen habt, entdeckt, {race}.\n\nEr hat uns zwar bereits sehr viele Informationen beschafft, aber es ist wichtig, dass wir weiter über jeden Schritt des Kultes informiert sind.\n\nBenutzt diese Rute, um den Körpern der versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um einen weiteren dunklen Boten zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", completion = "Gut gemacht, Freund.\n\nDer Bote ist bereits bei der Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13366] = { id = 13366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauche mehr Informationen", description = "Der Kult der Verdammten ist dafür berühmt, grandiose Pläne auszuarbeiten, die letzten Endes allerdings selten erfolgreich sind. Diesmal allerdings scheint es anders zu sein...\n\nVielleicht ist es die Nähe zum Lichkönig, die ihre Inbrunst angefacht hat. Was immer es auch ist, sie scheinen selbstbewusster denn je. Wir müssen herausfinden, was ihren Eifer befeuert und dieses dann ganz schnell unterbinden!\n\nIch glaube, dass der Schlüssel dazu ihre Forscher sind. Findet heraus, was sie im Schilde führen und berichtet mir dann.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr 3 Seiten Forschung der Kultisten von den Forschern der Kultisten in Aldur'thar sammelt, um damit eine These über den Kult der Verdammten zu erstellen...", progress = "Habt Ihr herausgefunden, was die Forscher im Schilde führen, {class}?", completion = "Das ist in der Tat alarmierend...", sourceObjectiveStatus = "unverified-source-field" }
quests[13367] = { id = 13367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann der Böseste nicht in Frieden ruhen...", description = "Die Dummköpfe sind übrigens über etwas gestolpert, das äußerst gefährlich für unsere Pläne werden könnte!\n\nAlumeth, der Anführer dieser Sekte, hat sich in einem Ritual selbst geopfert und nun versorgen seine Untergebenen seine Seele mit Macht.\n\nWenn wir ihn weiterhin in Ruhe lassen, werden sie ihn schon bald zu einem mächtigen Gegner machen.\n\nIn ihrer Kammer verteilt liegt sein Herz, Szepter, Schädel und seine Robe - kombiniert sie miteinander und benutzt das, was dabei rauskommt, in der Nähe der dortigen Kristalle.\n\nBeeilt Euch, {race}! Vernichtet ihn, bevor er noch mächtiger wird!", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar besiegt.", completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", sourceObjectiveStatus = "unverified-source-field" }
quests[13368] = { id = 13368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann der Böseste nicht in Frieden ruhen...", description = "Es ist Alumeth... Seine Macht wächst wieder an. Ich kann es fühlen. Wieder versorgen seine Untergebenen seine Seele mit Energie.\n\nWenn wir zulassen, dass er sich weiter erholt, werden ihre Bemühungen ihn zu einem mächtigen Gegner machen.\n\nKehrt in seine Kammer im Norden von Aldur'thar zurück. Sammelt sein Herz, seinen Schädel, sein Zepter und seine Kleider und wendet seine Überreste dann auf den Kristall dort an.\n\nEilt Euch, {race}! Vernichtet ihn, solange noch Zeit ist!", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar tötet.", completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", sourceObjectiveStatus = "unverified-source-field" }
quests[13369] = { id = 13369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal wendet sich gegen Euch", description = "Auf Geheiß von Lady Prachtmeer werde ich eine diplomatische Mission nach Orgrimmar entsenden, um Thrall, dem Kriegshäuptling der Horde, ein paar Fragen zu stellen. Ihr werdet ihr auf dieser Reise zur Seite stehen und dafür sorgen, dass ihr nichts zustößt. Kehrt anschließend mit Nachricht aus Orgrimmar zu mir zurück.\n\nSprecht mit Jaina, wenn Ihr bereit seid zu gehen.", sourceObjective = "Steht Lady Jaina Prachtmeer in Orgrimmar zur Seite. Sprecht mit Thrall, dem Kriegshäuptling der Horde in Orgrimmar auf dem Kontinent Kalimdor.", completion = "Die Horde will keinen Krieg, {race}. Hört gut zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[13370] = { id = 13370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein königlicher Coup", description = "Euer Champion Bolvar ist bei der Verteidigung unserer Welt ums Leben gekommen. Die Horde ist vom Verlust eines solch großen Helden schwer getroffen, jedoch war sie für die feigen Angriffe Putress' auf die Pforte des Zorns nicht verantwortlich. Wir haben auch Verluste unter unseren mächtigen Helden zu beklagen aufgrund dieses Verrats.\n\nSagt Eurem König, dass wir alles in unserer Macht stehende tun werden, um diejenigen, die für diese feige Tat verantwortlich sind, zur Rechenschaft zu ziehen. Wir werden alles tun, um einen Konflikt mit der Allianz zu vermeiden, doch wir werden nicht zögern, uns zu verteidigen, sollte man uns provozieren.", sourceObjective = "Benutzt das Portal in der Feste Grommash, um nach Burg Sturmwind zurückzukehren und Thralls Nachricht an König Varian Wrynn zu übergeben.", completion = "Sie haben die Unterstadt verloren? Dann ist jetzt der Augenblick gekommen, zuzuschlagen. Wir werden uns Putress höchstpersönlich vorknöpfen und die Ruinen von Lordaeron für die Allianz zurückerobern!", sourceObjectiveStatus = "unverified-source-field" }
quests[13371] = { id = 13371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist Zeit, totzuschlagen", description = "Bevor Ihr nach Orgrimmar aufgebrochen seid, habe ich Broll und Valeera nach Unterstadt entsandt. Um genau zu sein, sind sie gerade am Eingang zur Kanalisation stationiert und erwarten Befehl.\n\nLady Prachtmeer wird außerhalb der Unterstadt ein Portal für unsere Truppen erschaffen. Geht dorthin und meldet Euch bei Broll. Jaina und ich werden dicht hinter Euch sein.", sourceObjective = "Benutzt das Portal nach Unterstadt im Inneren von Burg Sturmwind, um Euch nach Unterstadt zu teleportieren. Meldet Euch bei Broll Bärenfell, wenn Ihr am Zielort angekommen seid.", completion = "Wer sollt Ihr sein? Varian hat gesagt, dass er Helden schicken würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13372] = { id = 13372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel der fokussierenden Iris", description = "Ihr spürt und hört, wie ein lautes Dröhnen magischer Natur von dem augenförmigen Juwel ausgeht, das Saphiron in seinen Klauen hielt. Für die Ohren eines Sterblichen ist es schon beinahe eine Qual, in Gegenwart des Steins zu sein.\n\nSolch ein bedeutungsvoller Gegenstand kann auf jeden Fall nur zur Königin der Großdrachen, Alexstrasza der Lebensbinderin, gebracht werden. Geht zur höchsten Ebene des Wyrmruhtempels in der Drachenöde und ersucht sie um Rat.", sourceObjective = "Liefert den Schlüssel zur fokussierenden Iris bei Alexstrasza der Lebensbinderin auf der höchsten Ebene des Wyrmruhtempels in der Drachenöde ab.", progress = "{name}, Ihr seid mit dem Schlüssel zur fokussierenden Iris in Berührung gekommen! Habt Ihr ihn dabei?\n\n\n\nWie konntet Ihr jemals in seinen Besitz gelangen? Oh, Saphiron hatte seinen Schlüssel noch immer?", completion = "Nur die ältesten Mitglieder des blauen Drachenschwarms sind in Besitz dieser Schlüssel. Malygos, ihr Meister, vertraut sie nur ihnen an.\n\nDas ist die Gelegenheit, auf die wir gewartet haben, um den Aspekt der Magie anzugreifen!<Die Königin der Drachen mustert Euch kurz.>\n\nIhr könnt mit dem Schlüssel, so wie er ist, keinen Zugang zur fokussierenden Iris erhalten, doch ich kann Euch mit einem Teil meiner Macht erfüllen; genug, um damit die Iris einen Spalt zu öffnen.\n\nEs wird genügen, um Malygos Zorn auf Euch zu ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13373] = { id = 13373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorzüge der Grenzwissenschaft", description = "Ich habe unsere Infragrüntechnologie in die beschlagnahmten Bomber eingebaut - das wird Euch auf eurer ersten Mission in Feindgebiet beschützen! Sprecht mit Rizzy Ratschenwackel, um einen Bomber zu bekommen, und fliegt dann zum Bombardement!\n\nIhr werdet Bomben, Raketen und Schilde haben. Sorgt dafür, dass Eure Schilde aufgeladen bleiben, und werft die Bomben auf die Diener der Geißel im Bombardement ab. Kommt zurück, nachdem Ihr Eure Ziele getroffen habt, und es wird Euch noch mehr Arbeit erwarten.", sourceObjective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 40 Bombardementinfanteristen, 8 Bombardementhauptmänner und 15 Gargoylewegelagerer tötet.", progress = "Ihr habt Eure Trefferquote noch nicht erfüllt, {name}. Sind die Bomber zu schwer zu fliegen?", completion = "Ha, Ihr habt sie erwischt! Wie hat Euch der Bomber gefallen? Ich hoffe, dass Ihr den Dreh raus habt, denn ich habe noch mehr Missionen für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[13374] = { id = 13374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit zur Revolte!", description = "{name}, nur unsere besten Piloten bekommen eine Mission wie diese. Eine Mission, bei der es sehr tief in Feindgebiet geht und bei der Ihr nur von Infragrüntechnologie beschützt werdet!\n\nBeantragt einen weiteren Bomber von Rizzel und fliegt mit ihm dieses Mal durch das Tal der Verlorenen Hoffnung. Bei dieser Mission habt Ihr Boden- und Luftziele - haltet also die Augen auf und sorgt dafür, dass Eure Schilde aufgeladen bleiben!\n\nViel Glück!", sourceObjective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr Bombardementinfanteristen, Gargoylewegelagerer, Frostbrutspäher und Kriegsmaschinen der Geißel vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13375] = { id = 13375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der heroische Schlüssel der fokussierenden Iris", description = "Ihr spürt und hört, wie ein lautes Dröhnen magischer Natur von dem augenförmigen Juwel ausgeht, das Saphiron in seinen Klauen hielt. Für die Ohren eines Sterblichen ist es schon beinahe eine Qual, in Gegenwart des Steins zu sein.\n\nSolch ein bedeutungsvoller Gegenstand kann auf jeden Fall nur zur Königin der Großdrachen, Alexstrasza der Lebensbinderin, gebracht werden. Geht zur höchsten Ebene des Wyrmruhtempels in der Drachenöde und ersucht sie um Rat.", sourceObjective = "Liefert den heroischen Schlüssel zur fokussierenden Iris bei Alexstrasza der Lebensbinderin auf der höchsten Ebene des Wyrmruhtempels in der Drachenöde ab.", progress = "{name}, Ihr seid mit dem Schlüssel zur Iris in Berührung gekommen! Habt Ihr ihn dabei?\n\n\n\nWie konntet Ihr jemals in seinen Besitz gelangen? Oh, Saphiron hatte seinen Schlüssel noch immer?", completion = "Nur die ältesten Mitglieder des blauen Drachenschwarms sind in Besitz dieser Schlüssel. Malygos, ihr Meister, vertraut sie nur ihnen an.\n\nDas ist die Gelegenheit, auf die wir gewartet haben, um den Aspekt der Magie anzugreifen!<Die Königin der Drachen mustert Euch kurz.>\n\nIhr könnt mit dem Schlüssel, so wie er ist, keinen Zugang zur fokussierenden Iris erhalten, doch ich kann Euch mit einem Teil meiner Macht erfüllen; genug, um damit die Iris einen Spalt zu öffnen.\n\nEs wird genügen, um Malygos Zorn auf Euch zu ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13376] = { id = 13376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totale Vernichtung: Das Tal der Verlorenen Hoffnung!", description = "{name}, der Kampf geht weiter. Zu unserem Glück haben wir uns mit Bomben und Raketen eingedeckt! Zeit für eine weitere Bombenmission - diese hier ist eine längere: Es geht über das Bombardement hinweg und zum Tal der Verlorenen Hoffnung. Setzt Euch wieder in einen Infragrünbomber, fliegt hinaus und verarbeitet die Diener der Geißel in kleine Geißelstückchen!", sourceObjective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 50 Bombardementinfanteristen, 20 Gargoylewegelagerer, 12 Frostbrutspäher und 12 Kriegsmaschinen der Geißel vernichtet.", completion = "Ausgezeichnete Arbeit, {name}. Während Ihr dort draußen wart, habe ich andere Schützen über Euch reden hören... Denke, dass Ihr eine echte Zukunft als Angriffsflieger habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13377] = { id = 13377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Unterstadt", description = "Tief im Inneren von Unterstadt versteckt er sich: der Meuchelmörder, der für den Tod Bolvars und den Tod unserer mutigen Soldaten an der Pforte des Zorns verantwortlich ist.\n\nVarian hat die geballte Macht der Allianz mitgebracht, um dabei zu helfen, die Stadt auseinanderzunehmen. Schließt Euch ihm und Lady Prachtmeer auf ihrer Jagd an und verdient Euch Euren Platz unter den größten Champions der Allianz!\n\nSprecht mit König Varian Wrynn, wenn Ihr bereit seid.", sourceObjective = "Helft König Varian Wrynn und Lady Jaina Prachtmeer, Großapotheker Putress zur Rechenschaft zu ziehen! Meldet Euch bei König Varian Wrynn, solltet Ihr erfolgreich sein.", completion = "Schon viel zu lange ist die Horde unbehelligt geblieben. Wir haben ihre Gebiete gedeihen lassen und als Gegenleistung für unsere Großzügigkeit haben sie daran gearbeitet, unseren Untergang herbeizurufen.\n\nFrieden? Zwecklos... nichts hat er uns gebracht. Wir haben einige unserer größten Helden an den \"Frieden\" verloren. Sehen wir einmal, was die Schlacht uns bringen wird...\n\nKehrt nach Nordend zurück, {name}. Erobert es für Euren König - FÜR DIE ALLIANZ!", sourceObjectiveStatus = "unverified-source-field" }
quests[13378] = { id = 13378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chefingenieur Kupferklammer", description = "Sprecht mit Chefingenieur Kupferklammer." }
quests[13379] = { id = 13379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüne Technologie", description = "Tezzla ist diejenige, nach der Ihr sucht, genau... sie beherrscht nun eine neue Wellenlänge namens Infragrün und hält sich damit in der Nähe der Geißel versteckt! Nahe genug, um Bomben auf sie abzuwerfen!\n\nIch werde Euch Infragrünsicht verleihen, damit Ihr sie sehen könnt. Sie befindet sich über Aldur'thar, dem Tor der Verwüstung. Geht, los, geht... ich weiß, dass sie Arbeit für mutige Helden hat, die scharf darauf sind, in die Luft zu fliegen! Äh, ich meine: die scharf darauf sind, die Geißel in die Luft fliegen zu lassen!\n\nUnd {name}, die Allianz hat unsere Technologie gestohlen und ihren eigenen versteckten Flugplatz in der Nähe errichtet. Haltet Euch von der Plattform mit den Bannern der Allianz fern!", sourceObjective = "Sprecht mit Grenzwissenschaftsingenieurin Tezzla.", completion = "Ja, ja! Ihr habt mich gefunden! Und gerade rechtzeitig!", sourceObjectiveStatus = "unverified-source-field" }
quests[13380] = { id = 13380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Angriff leiten", description = "Infragrüntechnologie ermöglicht es uns, hier versteckt zu bleiben - direkt unter der Nase der Geißel! Außerdem haben wir spezielle Bomber mit Infragrüntechnologie ausgerüstet... doch nicht um sie zu tarnen, nein! Wir benutzen die Technologie, um sie zu schützen!\n\nSprecht mit Karen Nein und fordert einen Bomber an. Fliegt mit ihm zum Bombardement... benutzt seine Schilde und sein Geschütz, um Euch zu schützen, und seinen Bombenwerfer, um die Ziele der Geißel zu treffen. Trainiert gut, kommt dann wieder zu mir zurück und ich werde eine noch wichtigere Mission für Euch haben!", sourceObjective = "Kibli Killohertz möchte, dass Ihr 40 Bombardementinfanteristen, 8 Bombardementkapitäne und 15 Gargoylewegelagerer tötet.", progress = "{name}, die Bomber sind schwierig zu fliegen, doch Ihr müsst sie beherrschen, wenn wir unseren Kampf gegen die Geißel gewinnen wollen.", completion = "Ich konnte die Explosionen von hier aus hören, {name}. Haben die Schilde gut funktioniert? Haben sie Euren Bomber intakt gehalten?\n\nIch hoffe, dass dem so ist, weil ich jetzt noch mehr Missionen für Euch habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[13381] = { id = 13381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watt ist mein Ziel", description = "Zieht Euch warm an, {name}, und fangt an zu beten. Diese nächste Mission wird Euren Verstand und Eure innere Stärke auf die Probe stellen wie ein Besuch der Schwiegereltern!\n\nFordert einen weiteren Bomber von Karen Nein an. Fliegt mit ihm über das Bombardement und das Tal der Verlorenen Hoffnung hinweg. Diesmal habt Ihr mehr Ziele, am Boden und in der Luft. Sorgt dafür, dass Euer Schutzschild und Eure Munition geladen ist, {name}! Ich werde Euch wiedertreffen, wenn die Sache vorbei ist.", sourceObjective = "Kibli Killohertz wünscht, dass Ihr Bombardementinfanteristen, Gargoylewegelagerer, Frostbrutspäher und Kriegsmaschinen der Geißel vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13382] = { id = 13382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission mit Hertz: Das Tal der Verlorenen Hoffnung", description = "Der Kampf geht weiter! Eure neuen Befehle sind hier. Es handelt sich um eine Langstreckenbombenmission zum Bombardement und zum Tal der Verlorenen Hoffnung. Fragt Karen nach einem Bomber und macht der Geißel mit Euren Bomben und Raketen die Hölle heiß!", sourceObjective = "Kibli Killohertz möchte, dass Ihr 50 Bombardementinfanteristen, 20 Gargoylewegelagerer, 12 Frostbrutspäher und 12 Kriegsmaschinen der Geißel vernichtet.", progress = "Einfach draufhalten, {name}. Der Luftkampf wird sich nicht von alleine gewinnen lassen!", completion = "Willkommen zurück, {name}. Wie war die Schlacht? Aufregend? Ruht Euch erst einmal aus. Doch kommt wieder zurück, wenn Ihr neue Befehle habt.\n\nFür die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[13383] = { id = 13383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killohertz", description = "Die Goblins hatten Glück: Sie haben eine neue Energie gefunden. Sie nennen sie Infragrün und ich soll ein einäugiger Oger sein, wenn diese Psychopathen damit keinen grünen Volltreffer gelandet haben.\n\nGeht und sucht nach Kibli Killohertz. Er befindet sich auf einem kleinen, versteckten Flugplatz der Allianz über Aldur'thar, dem Tor der Verwüstung, und ist dort für die umgekehrten Ingenieursbestrebungen in Bezug auf die Infragrüntechnologie zuständig. Ich werde Euch Infragrünsicht geben, damit Ihr ihn finden könnt. Geht zur Kuppel, auf der unsere Banner der Allianz wehen. Falls Ihr in der Nähe des Flugplatzes der Horde herumfliegen solltet, dann seid Ihr in jeder Menge grünen Schwierigkeiten.", sourceObjective = "Chefingenieur Bolzenschlüssel möchte, dass Ihr zum verborgenen Allianzflugplatz über Aldur'thar, dem Tor der Verwüstung, fliegt und Kibli Killohertz aufsucht.", completion = "Ja, ja, ja! So gut, Euch zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13384] = { id = 13384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entscheidung im Auge der Ewigkeit", description = "Es ist nun, da Ihr Zugang zur fokussierenden Iris habt, an der Zeit, dass Ihr vom Schlüssel Gebrauch macht.\n\nSo gerne ich Malygos wieder bei uns mit offenen Armen empfangen möchte, aber zu diesem Zeitpunkt wird dies einfach nicht möglich sein. Angesichts all dessen, was auf dem Spiel steht, haben sich die anderen Drachenaspekte dazu entschlossen, dass der Zauberwirker ausgeschaltet werden muss.\n\n<Krasus klingt sehr betroffen, als er diese letzen Worte ausspricht.>\n\n{name}, macht Euch auf den Weg zum Auge der Ewigkeit, begegnet Malygos und kehrt mit dem Herzen der Magie zurück.", sourceObjective = "Krasus auf der Spitze des Wyrmruhtempels in der Drachenöde möchte, dass Ihr mit dem Herzen der Magie zurückkehrt.\n\nDiese Quest ist für den normalen Modus, also für die 10-Mann-Version des Auges der Ewigkeit, gedacht.", progress = "Malygos und nur Malygos allein trägt das Herz der Magie bei sich. Es ist sein kostbarster Besitz.", completion = "Dies ist ein sehr trauriger Tag, nicht nur für uns Drachen, sondern für alle lebendigen Wesen Azeroths. Wir haben einen unserer nachdenklichsten, intelligentesten und ältesten Freunde verloren. Die Magie hat ihren Wächter verloren.\n\nLasst uns hoffen, dass sich dies in den kommenden Jahren als weise Entscheidung herausstellen wird, {name}. Am Horizont braut sich noch immer ein Sturm zusammen und uns fehlt einer unserer mächtigsten Verteidiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[13385] = { id = 13385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroische Entscheidung im Auge der Ewigkeit", description = "Es ist nun, da Ihr Zugang zur fokussierenden Iris habt, an der Zeit, dass Ihr vom Schlüssel Gebrauch macht.\n\nSo gerne ich Malygos wieder bei uns mit offenen Armen empfangen möchte, aber zu diesem Zeitpunkt wird dies einfach nicht möglich sein. Angesichts all dessen, was auf dem Spiel steht, haben sich die anderen Drachenaspekte dazu entschlossen, dass der Zauberwirker ausgeschaltet werden muss.\n\n<Krasus klingt sehr betroffen, als er diese letzen Worte ausspricht.>\n\n{name}, macht Euch auf den Weg zum Auge der Ewigkeit, begegnet Malygos und kehrt mit dem Herzen der Magie zurück.", sourceObjective = "Krasus auf der Spitze des Wyrmruhtempels in der Drachenöde möchte, dass Ihr mit dem Herzen der Magie zurückkehrt.\n\nDiese Quest kann sowohl in der 10-Mann-Version als auch in der 25-Mann-Version des Auges der Ewigkeit abgeschlossen werden.", progress = "Malygos und nur Malygos allein trägt das Herz der Magie bei sich. Es ist sein kostbarster Besitz.", completion = "Dies ist ein sehr trauriger Tag, nicht nur für uns Drachen, sondern für alle lebendigen Wesen Azeroths. Wir haben einen unserer nachdenklichsten, intelligentesten und ältesten Freunde verloren. Die Magie hat ihren Wächter verloren.\n\nLasst uns hoffen, dass sich dies in den kommenden Jahren als weise Entscheidung herausstellen wird, {name}. Am Horizont braut sich noch immer ein Sturm zusammen und uns fehlt einer unserer mächtigsten Verteidiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[13386] = { id = 13386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausnutzen einer Öffnung", description = "Ich habe eine interessante Aufgabe für Euch, {name}. Allerdings nur, wenn Ihr auf eine Herausforderung aus seid.\n\nWir haben von einer Öffnung unterhalb der Eiskronenzitadelle gehört. Unsere Ingenieure haben sie studiert und gehen davon aus, dass sie eine strukturelle Schwäche darstellt.\n\nWir haben ein paar Männer mit einer \"geborgten\" Ladung Saronitbomben dorthin entsandt. Sie stehen unter dem Kommando von Hauptmann Kendall.\n\nMit ein bisschen Hilfe könnten wir den Streitkräften der Geißel einen ordentlichen Schlag verpassen. Was sagt Ihr, {name}?", sourceObjective = "Redet mit Hauptmann Kendall unterhalb der Eiskronenzitadelle.", completion = "Seid gegrüßt, {name}. Thassarian sagte schon, dass Ihr kommen würdet. Jeder Freund von Thassarian ist auch mein Freund. Zumindest jeder lebende Freund... er umgibt sich mitunter mit seltsamer Gesellschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13387] = { id = 13387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Gebiets", description = "Die Saronitbomben sind platziert, {name}. Wir haben aber nur einen Versuch, also muss es unbedingt funktionieren.\n\nWir müssen für eine Weile die Kontrolle über das Gebiet haben, um eine sichere Detonation garantieren zu können. Lasst uns versuchen, die Anzahl der Geißel ein wenig zu reduzieren.", sourceObjective = "Kapitän Kendall bei der Eiskronenzitadelle möchte, dass Ihr 10 bullige Schrecken tötet.", progress = "Für die Allianz!", completion = "Ihr seid so gut, wie Thassarian gesagt hat. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[13388] = { id = 13388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie hochgehen!", description = "Das sieht doch schon mal alles recht gut aus. Also, gehen wir's an!\n\nDer Bombenstapel befindet sich gleich in der Nähe der Grube. Ich werde beginnen, die Männer zu evakuieren.", sourceObjective = "Hauptmann Kendall unterhalb der Eiskronenzitadelle möchte, dass Ihr die Lunte an dem nahegelegenen Saronitbombenstapel anzündet.", completion = "Diese Bomben sehen ziemlich durchschlagskräftig aus. Sie sollten zumindest eine ordentliche Delle in die umgebende Struktur machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13389] = { id = 13389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kurze Lunte", description = "Als Ihr die Lunte entzündet, merkt Ihr, dass sie viel schneller abbrennt, als Ihr erwartet hattet.\n\nDie Bomben sind kurz vor der Explosion und Eure beste Chance zu überleben ist, Euch nach vorne fallen zu lassen und zu hoffen, dass Euch der Sturz nicht tötet.", sourceObjective = "Haltet nach Hinweisen Ausschau, wo auch immer der Sturz Euch hinführt.", completion = "Dieses pulsierende Objekt ist von einer dicken Eisschicht umgeben. Es schimmert geheimnisvoll unter Wasser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13390] = { id = 13390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Stimme im Dunklen", description = "Das Objekt ist überhaupt kein Kristall, sondern etwas Organisches, das in Eis eingeschlossen ist.\n\nAls Ihr es berührt, zuckt Eure Hand vor Schmerz zurück. Es fühlt sich an, als hättet Ihr Euch in die Hand geschnitten, aber es ist keine Wunde zu sehen.\n\nAls Ihr Eure Gedanken sammelt, hört Ihr die Stimme eines Jungen in der Nähe.\n\n\"Das hättet Ihr nicht tun sollen.\"", sourceObjective = "Untersucht die nahe Stimme in Naz'anak, den Vergessenen Tiefen.", completion = "Ich sah, wie er es weggeworfen hat, wisst Ihr? Er hat es ganz bis hier herunter geworfen.\n\nSagte, er bräuchte es nicht mehr. Sagte, es würde ihn schwach machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13391] = { id = 13391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Verstecken", description = "Ihr hättet das nicht berühren sollen. Nun, da Ihr es getan habt, wird er kommen und nach Euch suchen.\n\nUnd er wird Euch finden. Solange Ihr Euch nicht vor ihm versteckt.\n\nBringt mir Blut von den Gesichtslosen, wenn Ihr leben wollt.", sourceObjective = "Matthias Lehner möchte, dass Ihr ihm 3 Proben Blut des Gesichtslosen bringt.", progress = "Habt Ihr das Blut?", completion = "Worauf wartet Ihr dann noch? Ihr müsst Euch damit einreiben!\n\nSchnell! Oder er wird Euch sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13392] = { id = 13392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr an die Oberfläche", description = "Ihr solltet nun gehen. Hinter mir findet Ihr ein Portal, das Euch an die Oberfläche bringen wird.\n\nWir werden uns wiedersehen. Er wird nach Euch suchen.\n\nEs ist nur eine Frage der Zeit, bis er Euch findet.", sourceObjective = "Kehrt zu Thassarian an Bord der Himmelsbrecher zurück.", completion = "Ihr seid es, {name}! Wir dachten schon, es hätte Euch erwischt.\n\nEure Explosion hat der Geißel ganz schön wehgetan. Und dabei fast noch Hauptmann Kendalls Augenbrauen weggesengt...", sourceObjectiveStatus = "unverified-source-field" }
quests[13393] = { id = 13393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldreparaturen", description = "Alles klar. Lasst uns aber nicht zu früh feiern. Wir müssen aus dem Vorteil, den wir mit unserer kleinen Bombardierung errungen haben, Kapital schlagen.\n\nWir haben ein funktionierendes Katapult der Verwüster-Klasse von der Horde auf dem Feld unten entdeckt. Die Spuke scheinen es auseinanderzunehmen.\n\nWenn Ihr es wieder zusammensetzen könntet, wären wir in der Lage, den Armeen der Geißel im Tal ernstlichen Schaden zuzufügen.\n\nKlar, Ihr werdet ziemlich in der Unterzahl sein, aber ich setze großes Vertrauen in Euch.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 Verwüsterersatzteile von den aasfressenden Spuken sammelt und sie zu dem defekten Verwüster im Tal der Verlorenen Hoffnung bringt.", progress = "Der Verwüster wurde stark beschädigt.", completion = "Der Verwüster hat schon bessere Tage gesehen, aber die Struktur hat keinen dauerhaften Schaden genommen. Die Ersatzteile, die Ihr gebracht habt, sollten ausreichen, um ihn zumindest vorübergehend wieder ans Laufen zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13394] = { id = 13394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Euer Schlechtestes", description = "Ihr werdet diese Maschine gegen die Geißel einsetzen? Auf diese Weise werdet Ihr nicht gegen sie gewinnen können.\n\nIhr könnt Hunderte... sogar Tausende von ihnen zerstören, doch gewinnen werdet Ihr nicht - nicht hier draußen.\n\nTrefft mich im Norden, wenn Ihr genug mit Eurer Maschine gespielt habt. Dort gibt es ein altes Militärlager. Was ich Euch zeigen werde, wird Euch einen kleinen Einblick darüber gewähren, wem wir uns hier gegenübersehen.", sourceObjective = "Zerstört mithilfe des Runderneuerten Verwüsters 150 verrottete Ghule, 20 Frostschädelmagier und 2 Knochenriesen im Tal der Verlorenen Hoffnung. Sprecht mit Matthias Lehner im Vorhutslager der Ersten Legion, wenn Ihr die Aufgabe abgeschlossen habt.", progress = "Habt Ihr genug mit Euren Kriegsmaschinen gespielt?", completion = "Seht Ihr? Ihr habt Euren gerechten Anteil zwar getötet, doch für jeden Einzelnen, den Ihr vernichtet habt, kam ein weiterer aus der Erde, um dessen Platz einzunehmen.\n\nIhr wisst nicht, wem Ihr hier gegenübersteht, {name}. Lasst es mich Euch zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13395] = { id = 13395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armee der Verdammten", description = "Ihr meint wohl, Ihr seid ziemlich stark... diese Untoten zu bekämpfen und ihre Knochen mit Euren Kriegsmaschinen zu zerquetschen.\n\nDas ist aber noch gar nichts, verglichen mit der Stärke, derer es bedarf, um sie zu erschaffen.\n\nIch habe selbst gesehen, wie der Prinz es gemacht hat. Ich kann Euch zeigen, wie das geschehen ist... wenn Ihr wollt.", sourceObjective = "Matthias Lehner beim Vorhutslager der Ersten Legion möchte, dass Ihr eine Armee von 100 ghulischen Dienern aufstellt.", completion = "Die wahre Stärke des Prinzen lag nicht darin, Armeen aus Leichen zu erschaffen... das war leicht.\n\nAber seine eigenen Männer zu töten, mit denen er in vielen Schlachten Seite an Seite gefochten hatte... die wahre Stärke des Prinzen war seine Fähigkeit, zu tun, was getan werden musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[13396] = { id = 13396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinnlosigkeit", description = "Seht Ihr es nun? Eure Männer gegen die Armeen des Prinzen zu entsenden sorgt nur dafür, dass ihre Reihen weiter anwachsen.\n\nIch erwarte nicht, dass Ihr es versteht... Ihr werdet vermutlich auch wie die anderen enden. Am besten kehrt Ihr zu denjenigen zurück, die Euch entsandt haben. Sie werden sich Sorgen machen.", sourceObjective = "Kehrt zu Thassarian an Bord der Himmelsbrecher zurück.", completion = "Gut geschossen, {name}. Die Geißel hatte keine Chance.\n\nGeht es Euch gut? Ihr seht aus, als hättet ihr einen Geist gesehen. Naja, wenn ich so darüber nachdenke, wäre das in diesen Gegenden kein wirklich unüblicher Anblick.", sourceObjectiveStatus = "unverified-source-field" }
quests[13397] = { id = 13397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sindragosas Sturz", description = "Ihr seid ein echter Star, {name}. Wisst Ihr, wenn ich einem der anderen Soldaten einen Auftrag erteile, stehen die Chancen, dass er ihn erfolgreich ausführt, etwa fünfzig zu fünfzig. Die Chancen, dass er lebend zurückkommt... nun, unwesentlich schlechter.\n\nAber bei Euch ist die Sache stets geritzt. Zuverlässig wie ein gnomisches Uhrwerk!\n\nWie dem auch sei, ich habe noch einen für Euch. Sindragosas Sturz, im Osten des Tals. Dort gehen verstärkte Aktivitäten der Kultisten vor sich, inklusive und sich nicht beschränkend auf die Erschaffung von Frostwyrm. Ich brauche Euch, um denen mal ordentlich die Zähne einzutreten.\n\nIch hasse Kultisten.", sourceObjective = "Thassarian an Bord Himmelsbrecher möchte, dass Ihr 5 Wyrmwiedererwecker, 8 Verderber der Kultisten und 3 Nekrolords der Vrykul in Sindragosas Sturz tötet.", completion = "Gute Arbeit, {name}. Neben Euch verblasst der Rest von uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[13398] = { id = 13398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Drachen einst fielen", description = "Einst fiel hier eine ganze Brut von blauen Drachen. Und nun wird jeder einzelne von ihnen von seinen Dienern wiedererweckt.\n\nDen größten von ihnen hat er selbst wiedererweckt. Bringt mir ein wenig Knochenstaub von ihren Welpen und ich werde Euch ganz genau zeigen, wie er das gemacht hat.", sourceObjective = "Matthias Lehner in Sindragosas Sturz möchte, dass Ihr 6 Einheiten Welpenknochenstaub besorgt.", progress = "Habt Ihr den Staub bekommen, {name}?", completion = "Selbst die mächtigen Wyrm mussten seinem Ruf folgen. Wie könnte ein einfacher Sterblicher wie Ihr ihm widerstehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13399] = { id = 13399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Antworten", description = "Ihr habt viele Fragen, {name}. Ihr seid <der Einzige, der/die Einzige> die; mich sehen kann, weil Ihr etwas berührt habt, das einst ihm gehörte... könnt Ihr Euch nicht mehr erinnern?\n\nIhr wisst nicht, was es ist? Nun, ich kann es Euch nicht einfach so sagen... das würde ihn ziemlich wütend machen. Er ist nicht mehr bloß ein Prinz... er ist jetzt der König!\n\nTrefft mich im Hof der Knochen nördlich der Eiskronenzitadelle und Ihr könnt es für Euch selbst sehen.", sourceObjective = "Sprecht mit Matthias Lehner im Hof der Knochen.", completion = "Da seid Ihr ja. Ich habe mich schon gefragt, wann Ihr auftauchen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13400] = { id = 13400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jäger und der Prinz", description = "Bevor der Prinz König wurde, schlug er viele Schlachten... doch nur bei einer wäre er beinahe gestorben.\n\nSie fand genau hier statt. Nachdem ich Euch gezeigt habe, was hier einst geschah, werdet Ihr verstehen.\n\nSucht nach einem blutbefleckten Stein und hebt ihn auf. Ihr werdet sehen, was einst geschah.", sourceObjective = "Matthias Lehner im Hof der Knochen möchte, dass Ihr nach einem blutbefleckten Stein sucht und das Schicksal des Prinzen zu Ende bringt.", completion = "Nach dem Kampf erkannte der Prinz, dass das, was ihn zurückhielt, seine Menschlichkeit war... Er konnte noch immer fühlen... konnte noch immer bluten. Er hatte noch immer ein Herz.\n\nSeine erste Handlung als König war es, sein Herz loszuwerden. Er warf es die Grube hinunter, in der wir uns zum ersten Mal begegneten. Und Ihr, {name}, wart der Erste, der es seitdem berührt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13401] = { id = 13401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist eine schreckliche Bürde", description = "Jetzt wisst Ihr, womit Ihr es zu tun habt, {name}. Ein Gegner, der keinen Schmerz mehr kennt... keine Zweifel... und auch keine Menschlichkeit. Ein Gegner, der alles tun würde, um das zu bekommen, was er will.\n\nDas Herz war seine Schwachstelle und er weiß jetzt, dass Ihr es gefunden habt.\n\nWenn Ihr zurückwollt, um es zu holen, dann nehmt Euch besser Hilfe mit. Er wird es nicht noch einmal unbewacht lassen.", sourceObjective = "Meldet Euch bei Thassarian an Bord der Himmelsbrecher.", completion = "Immer langsam, {name}. Wieso fangt Ihr nicht einfach noch mal von vorne an... von ganz vorne.", sourceObjectiveStatus = "unverified-source-field" }
quests[13402] = { id = 13402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirions Hilfe", description = "Es ist nicht das erste Mal, dass ich die Geschichte über Arthas und sein Herz gehört habe... habe immer gedacht, dass es eine erfundene Geschichte für gewöhnliche Soldaten wäre.\n\nWir müssen umgehend danach handeln. Leider müssen wir das Ganze geheim halten.\n\nArthas' Agenten sind überall und wenn er es herausfindet, wäre unser Plan zunichte.\n\nWir müssen dies zum Argentumkreuzzug bringen. Jeder einzelne Paladin in dem Orden wurde von Tirion höchstpersönlich erlesen. Wenn irgendwer noch nicht von den Kultisten infiltriert wurde, dann sind es diese Jungs.", sourceObjective = "Sprecht mit Hochlord Tirion Fordring auf dem Kreuzfahrerturm.", completion = "Harte Worte, {name}. Hätte jemand anderes das gesagt, hätte ich ihn wahrscheinlich für verrückt erklärt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13403] = { id = 13403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirions Schachzug", description = "Diesen Morgen haben mich meine Späher darüber informiert, dass eine Prozession des Kults der Verdammten mit einem Artefakt von der Eiskronenzitadelle in Richtung Kathedrale der Dunkelheit aufgebrochen ist.\n\nUnd nun wird mir gesagt, dass es sich hierbei um Arthas' eigenes Herz handelt... ein Gegenstand, der den letzten Rest seiner Menschlichkeit enthält.\n\nDies ist ein Zeichen des Lichts. Solange solch ein Artefakt existiert, besteht eine Chance, dass Arthas Menethil wieder ein Mensch werden kann!\n\nTrefft mich am Eingang der Kathedrale. Bringt auf jeden Fall eine Kultistenverkleidung mit - wir gehen inkognito.", sourceObjective = "Tirion Fordring auf dem Kreuzfahrerturm möchte, dass Ihr die Kultistenkapuze besorgt, diese anzieht und Euch mit ihm am Eingang zur Kathedrale der Dunkelheit nordwestlich der Eiskronenzitadelle trefft.", completion = "Ich betrachte das, was wir soeben durchgemacht haben, nicht als Fehlschlag, {name}... im Gegenteil.\n\nDadurch, dass ich einen Blick in sein Herz werfen konnte, habt Ihr mir erlaubt, das zu bestätigen, was ich wissen musste. Es gibt keinen Arthas Menethil mehr - nur noch den Lichkönig.", sourceObjectiveStatus = "unverified-source-field" }
quests[13404] = { id = 13404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Statische Schocktruppen: das Bombardement", description = "Dies wird ein Kurzstreckeneinsatz, über das Bombardement. Gut zum warm werden. Bereit?", sourceObjective = "Kibli Killohertz möchte, dass Ihr 50 Bombardementinfanteristen, 10 Bombardementkapitäne und 20 Gargoylewegelagerer tötet.", progress = "Bleibt dran, {name}. Der Luftkrieg gewinnt sich nicht von selbst!", completion = "Willkommen zurück, {name}. Eine kurze Mission, aber belebend, was? Macht erstmal 'ne Pause. Aber kommt zurück, sobald Ihr neue Befehle habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13405] = { id = 13405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Strand der Uralten", description = "Wir kämpfen in Nordend nicht nur gegen die Armeen des Lichkönigs, sondern auch gegen die Armeen der Horde.\n\nAuf dem Strand der Uralten wurde ein mächtiges Titanenrelikt gefunden. Wie Ihr vielleicht schon wisst, sind wir Zwerge seit Jahren Hüter solcher Artefakte gewesen und sind deswegen auch ihre rechtmäßigen Besitzer.\n\nIn diesem Fall ist die Horde sehr scharf darauf, das Relikt aus den Titanenruinen zu klauen. Sie werden es sicherlich als Waffe gegen uns einsetzen - wir müssen sie also um jeden Preis aufhalten.", sourceObjective = "Gewinnt eine Schlacht auf dem Strand der Uralten und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Ausgezeichnete Arbeit, {name}! Mit Eurer Hilfe wird der komplette Strand der Uralten der Allianz zufallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13406] = { id = 13406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf derselben Wellenlänge: Das Bombardement", description = "Bereit, Euch mit einer kurzen Bombenmission aufzuwärmen? Ihr habt Eure Befehle und wir unsere Bomber - bestückt und bereit.", sourceObjective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 50 Bombardementinfanteristen, 10 Bombardementhauptmänner und 20 Gargoylewegelagerer tötet.", progress = "Ihr habt Eure Trefferquote noch nicht erfüllt, {name}. Los, raus da mit Euch und jagt etwas in die Luft!", completion = "Ha, Ihr habt sie erwischt! Ich konnte hören, wie einzelnen Körperteile der Geißel die Bergwand herunterrasselten. Gute Arbeit. Wir werden schon bald noch mehr für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13407] = { id = 13407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Strand der Uralten", description = "Nur weil wir in Nordend einmarschieren, um die Geißel zu vernichten, muss das noch lange nicht heißen, dass wir der Allianz eine Pause gönnen.\n\nDie Zwerge von der Forscherliga haben ein mächtiges Titanenrelikt gefunden und der Blitz soll uns treffen, wenn wir es einfach der Allianz überlassen.\n\nGeht, {name}, und vernichtet unsere Feinde. Sie sollen wissen, dass, egal wo wir uns auch begegnen, sie weiterhin unsere Todfeinde sind.", sourceObjective = "Gewinnt eine Schlacht auf dem Strand der Uralten und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[13408] = { id = 13408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, {name}, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", completion = "Gut gemacht, {name}. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13409] = { id = 13409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", completion = "Gute Arbeit, {name}. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13410] = { id = 13410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, {name}, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", completion = "Gut gemacht, {name}. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13411] = { id = 13411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", progress = "Kehrt zu mir zurück, wenn Ihr bei der Einnahme der Befestigungsanlagen geholfen habt!", completion = "Gute Arbeit, {name}. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13412] = { id = 13412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corastrasza", description = "Grüße, {class}. Dürfte ich Euch um einen Gefallen bitten?\n\nCorastrasza ist die Schwester von Raelorasz - dem roten Drachen, der hier in unserem Außenposten das Sagen hat. Sie ist gegen seinen Willen zu einem der oberen Nexusringe geflogen, um ein paar blaue Drachen, die über fürchterliche Macht verfügen, zu beobachten.\n\nEr macht sich um sie Sorgen, obwohl er es nie zugeben wird, und würde jegliche Neuigkeiten über ihr Wohlergehen begrüßen.\n\nSeid so gut und sucht sie auf. Bittet sie, ihren Stolz beiseite zu legen und ihrem Bruder eine Nachricht zu schicken.", sourceObjective = "Bibliothekarin Serrah möchte, dass Ihr mit Corastrasza in Kaltarra sprecht.", completion = "Es ist ziemlich anmaßend, Euch in die persönlichen Angelegenheiten eines Drachen einzumischen, meint Ihr nicht, {race}?\n\nDoch abgesehen davon, wäre es nicht richtig, meinem Bruder vorzuenthalten, dass es mir gut geht. Ihr könnt Eurer aufdringlichen Freundin sagen, dass ich meinen Bruder über das, was ich mache, auf dem Laufenden halten werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13413] = { id = 13413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht in den Wolken", description = "Ihr besitzt den Mut, Euch so nah an Malygos' Hort heranzuwagen, <Sterblicher/Sterbliche>? Oder ist es einfach nur Ignoranz? Bald werden wir es wissen...\n\nIch bin ein erfahrener Ausbilder der anmutigen Drachen des roten Drachenschwarms. Meine Aufgabe hier ist es, den Feind zu studieren und meinen kostbaren Begleitern die Taktiken beizubringen, die sich am effektivsten gegen den Meister der Blauen erweisen werden.\n\nDamit Ihr zeigen könnt, ob Ihr die Nerven und das Können besitzt, werde ich Euch erlauben, auf einem meiner Drachen in den Kampf gegen die Untergebenen des Feindes zu reiten.\n\nDie Möglichkeit besteht - Ihr müsst nur danach fragen...", sourceObjective = "Corastrasza auf dem oberen Ring des Nexus' in Kaltarra möchte, dass Ihr auf ihrem Drachen 5 Elitesoldaten der Eidschuppen tötet.", progress = "Tja, Sterblicher, was haltet Ihr von meinen Begleitern?", completion = "Mein Drache sagt mir, dass Ihr es mit ein wenig Übung zu einem fähigen Kämpfer machen könntet.\n\nNun gut. Im Interesse unseres Krieges mit Malygos werde ich Euch erlauben, nach Belieben mit einem meiner Begleiter zu trainieren.\n\nBereitet Euch vor, {race}, denn er ist ein heftiger und gnadenloser Gegner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13414] = { id = 13414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht in den Wolken", description = "So sehen wir uns wieder, {race}. Ich muss zugeben, dass Ihr mir langsam ans Herz wachst.\n\nLiege ich richtig in der Annahme, dass Ihr gekommen seid, um Eure Luftkampffertigkeiten zu verbessern?\n\nMeine Begleiter stehen wie immer bereit, Ihr zerstörerisches Feuer über den Feind zu ergießen.\n\nSprecht nur ein Wort und sie werden Euch zur Verfügung stehen.", sourceObjective = "Corastrasza auf dem oberen Ring des Nexus' in Kaltarra möchte, dass Ihr auf ihrem Drachen 5 Elitesoldaten der Eidschuppen tötet.", progress = "Ja, {race}?", completion = "Ich habe heute eine leichte Steigerung bemerkt, {class}. Es gab Momente, in denen es so schien, als wäret Ihr eins mit dem Drachen.\n\nIhr könnt gerne nach Eurem Belieben mit meinen kostbaren Begleitern trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13415] = { id = 13415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bibliothekenkonsole", description = "Norgannons Schale liegt in Reichweite, {name}. Bringt die Scheibe des Erfinders ins Innere der Bücherei. Dort sollte sich eine Konsole befinden, die Ihr mithilfe der Scheibe aktivieren könnt. Ich kann mir vorstellen, dass Mimir dort mehr als nur Norgannons Schale versteckt hat. Es befinden sich wahrscheinlich genug Schemata dort, um die Ingenieure von Eisenschmiede über Jahre hinweg zu beschäftigen!\n\nJedenfalls sollt Ihr die Scheibe dazu benutzen, um die Schale zu besorgen. Hoffentlich hat Mimir sich nicht dazu entschlossen, noch mehr Hindernisse in Euren Weg zu stellen.", sourceObjective = "Bringt die Scheibe des Erfinders zur Bibliothekenkonsole des Erfinders im Inneren der Bibliothek des Erfinders.", progress = "Auf der Konsole befindet sich eine Öffnung, die anscheinend für die Scheibe des Erfinders gedacht ist.", completion = "<Ihr schiebt die Scheibe in die Konsole. Plötzlich erscheinen Lichter auf deren Oberfläche und eine mechanische Stimme sagt:>\n\nScheibe des Erfinders bestätigt. Willkommen zurück, Hüter Mimir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13416] = { id = 13416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bibliothekenkonsole", description = "Norgannons Schale liegt in Reichweite, {name}. Bringt die Scheibe des Erfinders ins Innere der Bücherei. Dort sollte sich eine Konsole befinden, die Ihr mithilfe der Scheibe aktivieren könnt. Ich kann mir vorstellen, dass Mimir dort mehr als nur Norgannons Schale versteckt hat. Es befinden sich wahrscheinlich genug Schemata dort, um die Ingenieure von Eisenschmiede über Jahre hinweg zu beschäftigen!\n\nJedenfalls sollt Ihr die Scheibe zur Konsole bringen. Hoffentlich hat Mimir sich nicht dazu entschlossen, noch mehr Hindernisse in Euren Weg zu stellen.", sourceObjective = "Bringt die Scheibe des Erfinders zur Bibliothekenkonsole des Erfinders im Inneren der Bibliothek des Erfinders.", progress = "Auf der Konsole befindet sich eine Öffnung, die anscheinend für die Scheibe des Erfinders gedacht ist.", completion = "<Ihr schiebt die Scheibe in die Konsole. Plötzlich erscheinen Lichter auf deren Oberfläche und eine mechanische Stimme sagt:>\n\nScheibe des Erfinders bestätigt. Willkommen zurück, Hüter Mimir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13417] = { id = 13417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Bronzebart", description = "Das war's! Wir haben endlich den Schlüsselstein... Er ist schön! Ich bin schon mehr als einmal um die ganze Welt gereist, aber wegen diesem Ding war ich wieder so aufgeregt wie ein kleines Kind. Allerdings dürfte jetzt wohl nicht der richtige Zeitpunkt sein, um durchzuatmen und den Stein zu bewundern. Wir müssen von hier verschwinden.\n\nSteigt auf meine Flugmaschine und sorgt für Deckung, damit wir bei unserer Flucht vor diesen Eisenzwergen geschützt sind!", sourceObjective = "Begleitet Brann Bronzebart und seine Flugmaschine zur Eisfestung.", sourceObjectiveStatus = "unverified-source-field" }
quests[13418] = { id = 13418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorbereitung", description = "Ihr da!\n\nIhr seht aus, als hättet Ihr etwas auf dem Kasten. Wir könnten ein paar fähigere Leute in Eiskrone gebrauchen.\n\nIhr habt vielleicht die Gerüchte über unseren fehlgeschlagenen Bodenangriff auf den Gletscher gehört, doch lasst mich Euch beruhigen. Wir führen unseren Angriff jetzt von einem der fortgeschrittensten Gefährte aus, die es in Azeroth gibt: die Himmelsbrecher. Die Horde hat keine Chance und auch Arthas nicht.\n\nSagt mir Bescheid, wenn Ihr bereit seid, aufzubrechen.", sourceObjective = "Sprecht mit Offizier Van Rossem, um Euch sicher zur Himmelsbrecher in Eiskrone bringen zu lassen, und meldet Euch dann bei Stabshauptmann Justin Bartlett.", completion = "Willkommen auf der Himmelsbrecher.\n\nVon hier aus werden wir die Vorarbeit für unseren Angriff auf Arthas leisten. Es gibt noch viel zu tun, doch bevor wir uns ins eigentliche Getümmel stürzen können, wollen wir sichergehen, dass der Argentumkreuzzug ausreichend Verstärkung erhalten hat - wir werden später ihre Hilfe benötigen.\n\nSprecht mit Absalan dem Frommen auf dem Hauptdeck, wenn Ihr das nicht schon getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13419] = { id = 13419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorbereitung", description = "Ihr da!\n\nIhr seht aus, als hättet Ihr etwas auf dem Kasten. Wir könnten ein paar fähigere Leute in Eiskrone gebrauchen.\n\nDie Hunde von der Allianz sind vor uns nach Eiskrone geeilt, unvorbereitet, und haben für ihre Ungeduld genau das bekommen, was sie verdienen. Wir haben uns Zeit gelassen, haben uns vorbereitet und schon bald werden wir den echten Angriff starten - von einem der fortgeschrittensten Gefährte in ganz Azeroth aus: der Orgrims Hammer. Die Allianz hat keine Chance und auch Arthas nicht.\n\nSagt mir Bescheid, wenn Ihr bereit seid, aufzubrechen und zu helfen.", sourceObjective = "Sprecht mit Himmelshäscher Klum, um Euch sicher zur Orgrims Hammer in Eiskrone bringen zu lassen, und meldet Euch dann bei Himmelshäscher Korm Schwarznarbe.", completion = "Willkommen auf der Orgrims Hammer.\n\nVon hier aus werden wir die Vorarbeit für unseren Angriff auf Arthas leisten. Es gibt noch viel zu tun, doch bevor wir uns ins eigentliche Getümmel stürzen können, wollen wir sichergehen, dass der Argentumkreuzzug ausreichend Verstärkung erhalten hat - wir werden später ihre Hilfe benötigen.\n\nSprecht mit Bruder Keltan auf dem Hauptdeck, wenn Ihr das nicht schon getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13420] = { id = 13420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immerfrost", description = "Dieses Stück Eis war enormen Kräften und natürlicher Magie aus den Tiefen der Erde ausgesetzt. Zusammen haben diese Effekte ein Eis geschaffen, das niemals schmelzen wird.\n\nDa Ihr Euch in solchen Dingen nur wenig auskennt, entschließt Ihr Euch, die Probe zurück nach Dun Niffelem zu bringen. Dort muss es irgendjemanden geben, der mit dessen Eigenschaften vertraut ist.", sourceObjective = "Ihr müsst nach Dun Niffelem zurückkehren und Euch bei Calder über das Stück Immerfrost erkundigen.\n\nBereitgestellter Gegenstand:", completion = "<Das Licht des Immerfrosteises leuchtet in Calders Augen, als er es hochhält.>\n\nAhh, Immerfrost - Symbol des Herzens meines Volkes...\n\nImmerfrost gab es einst in dieser Region in Hülle und Fülle. Doch im Laufe der Zeit haben die Jormungar beinahe alles verschlungen. Heute ist es sehr selten und äußerst wertvoll für mein Volk.\n\nHaltet auf Euren Reisen durch dieses Land nach noch mehr Stücken Immerfrosts Ausschau. Bringt mir alles, was Ihr finden könnt, und wir werden überaus dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13421] = { id = 13421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst das Immerfrosteis nicht!", progress = "Habt Ihr noch mehr Immerfrost gefunden, kleiner {race}?", completion = "Gut gemacht, kleiner {class}.\n\nImmerfrost gab es einst in dieser Region in Hülle und Fülle. Doch im Laufe der Zeit haben die Jormungar beinahe alles verschlungen. Heute ist es sehr selten und äußerst wertvoll für mein Volk.\n\nHaltet auf Euren Reisen durch dieses Land nach noch mehr Stücken Immerfrosts Ausschau. Bringt mir alles, was Ihr finden könnt, und wir werden überaus dankbar sein." }
quests[13422] = { id = 13422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disziplin bewahren", description = "Ihr habt das geschafft, woran andere gescheitert sind. Doch auf Euren Lorbeeren könnt Ihr Euch noch nicht ausruhen.\n\nIhr müsst anderen zeigen, was Stärke und Engagement wirklich bedeuten.\n\nDie Aufsässigen in der verlorenen Mine müssen wieder einmal diszipliniert werden. Zeigt es ihnen, Schwester... zeigt ihnen, was es bedeutet, uns nicht zu gehorchen.", sourceObjective = "Gretta die Schiedsfrau aus Brunnhildar möchte, dass Ihr die Disziplinarrute auf 6 erschöpfte Vrykul in der verlassenen Mine anwendet.", completion = "Ihr geht weiterhin mit gutem Beispiel voran. Wir sehen zu Euch auf, Schwester.", sourceObjectiveStatus = "unverified-source-field" }
quests[13423] = { id = 13423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euren Titel verteidigen", description = "Alle sind von Eurer Leistung beeindruckt, Schwester. Doch lasst Eure Deckung nicht sinken. Jeder neue größenwahnsinnige Herausforderer wird jetzt herauskommen und sich Euren Titel als Hyldskvinnar schnappen wollen.\n\nZeigt diesen Emporkömmlingen, aus welchem Holz Ihr geschnitzt seid.", sourceObjective = "Gretta die Schiedsfrau in Brunnhildar wünscht, dass Ihr 6 siegreiche Herausforderinnen besiegt.", progress = "Wir verbeugen uns vor Eurer Kraft, Schwester.", completion = "Ihr erweist Euch weiterhin als würdig. Eure Anwesenheit ehrt uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[13424] = { id = 13424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Grube", description = "Um auch weiterhin wirklich gut reiten zu können, werdet Ihr Euch jeden Tag gegen die Hyldnir beweisen müssen.\n\nBegebt Euch zurück zur Reißzahngrube und zeigt ihnen, wozu Ihr fähig seid. Sie werden dankbar sein, gegen jemanden zu verlieren, der so geschickt ist wie Ihr.", sourceObjective = "Gretta die Schiedsfrau aus Brunnhildar möchte, dass Ihr in die Reißzahngrube geht und mit den Zügeln der Kriegsbärenmatriarchin 6 Kriegsbären des Hildarthings besiegt.", completion = "Ihr beweist auch weiterhin, was Ihr könnt. Eure Schwestern respektieren Euch noch immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[13425] = { id = 13425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Missgeburten müssen sterben", description = "Euer Können unter Euresgleichen zu beweisen, ist nicht genug. Ihr müsst auch gegen unsere Feinde kämpfen, liebe Schwester.\n\nDie Valkyrionverräter verhöhnen weiterhin unsere edlen Drachenreittraditionen, indem sie verseuchte Protodrachen großziehen.\n\nKommt in den Besitz ihres Frostöls, das sie bei sich tragen, und benutzt es, um ihre widerwärtigen verseuchten Eier einzufrieren.", sourceObjective = "Gretta die Schiedsfrau in Brunnhildar möchte, dass Ihr nach Valkyrion geht und Phiolen mit Frostöl von den Streiterinnen von Valkyrions besorgt. Nutzt die Phiolen dann, um 30 verseuchte Eier der Protodrachen zu zerstören.", completion = "Ihr seid in mehr als nur einer Hinsicht eine Anführerin. Wir danken Euch, Schwester.", sourceObjectiveStatus = "unverified-source-field" }
quests[13426] = { id = 13426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeuge Xarantaur", description = "Scheint, als wären wir nicht die einzigen Besucher dieser Gegend. Ein Kurier hat eine Nachricht von einem Tauren namens Xarantaur weitergeleitet, der gemeint hat, er habe ein Taunkadorf namens Camp Tunka'lo besucht. Der Zettel war zwar etwas kryptisch geschrieben, doch es scheint, als sei dieser Xarantaur in die Sturmgipfel gegangen, um der Geschichte einer Taunkalegende nachzugehen.\n\nTrefft Euch mit ihm, {name}. Seht nach, ob das, was er weiß, uns in irgendeiner Art und Weise behilflich sein kann. Seiner Beschreibung nach befindet sich Camp Tunka'lo weit gen Osten, jenseits der Terrasse der Schöpfer und nördlich von Dun Niffelem.", sourceObjective = "Sprecht mit Xarantaur im Camp Tunka'lo.", completion = "Boktar hat also meine Nachricht erhalten? Das sind ausgezeichnete Neuigkeiten. Ich habe bezweifelt, ob der Träger, ein Fernläufer der Taunka, überhaupt irgendjemanden erreichen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13427] = { id = 13427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, {name}, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", completion = "Genau das wollte ich hören! Ein Sieg im Alteractal, auch wenn er nur vorübergehend ist, wird uns den weiteren Kampf gegen die Horde enorm erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13428] = { id = 13428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.\n\nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.\n\nGeht nun, {name}. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", completion = "Es gibt nichts Ehrenvolleres, als die feindlichen Invasoren aus dem Gebiet der Horde zu vertreiben. Ich verneige mich vor Eurem Mut und danke Euch dafür, dass Ihr unseren Streitkräften heute einen großen Dienst erwiesen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13429] = { id = 13429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ablenkungsmanöver für Akama", description = "<Licht pulsiert um Xi'ri herum während die Streitkräfte der Aldor und der Seher seine Befehle ausführen. Xi'ris Armee ist bereit, Illidans Streitkräfte zurückzudrängen und Akama das nötige Ablenkungsmanöver zu verschaffen. Der Naaru wartet auf Eure Aufforderung den Angriff durchzuführen.>", sourceObjective = "Stellt sicher, dass Akama und Maiev den Schwarzen Tempel betreten, nachdem Xi'ris Streitkräfte ihr Ablenkungsmanöver durchgeführt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13430] = { id = 13430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Magtheridon", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft Euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13431] = { id = 13431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Knüppel von Kar'desh", description = "Bringt mir die Elementarsiegel, die ich für den Knüppel brauche!\n\nDas Erdensiegel befindet sich im Besitz von Gruul dem Drachenschlächter. Ihr findet ihn in seinem Unterschlupf im Schergrat.\n\nDas zweite Siegel ist das flammende Herz einer Kreatur, die als Schrecken der Nacht bekannt ist. Diese mystische Kreatur soll sich angeblich in den geheiligten Hallen des Propheten Medivh aufhalten.\n\nBeeilt Euch!", sourceObjective = "Nar'biss der Ketzer in den heroischen Sklavenunterkünften des Echsenkessels möchte, dass Ihr ihm das Erdensiegel und das Flammensiegel bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13432] = { id = 13432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Phiolen der Ewigkeit", description = "Illidan entnahm sieben Phiolen aus dem Brunnen der Ewigkeit. Eine davon leerte er in den See auf dem Berg Hyjal, wodurch ein zweiter Brunnen der Ewigkeit entstand. Jahrelang dachten wir, dass der Rest verlorengegangen sei.\n\nNach der Öffnung des Dunklen Portals haben wir erfahren, dass er seinen Leutnants Kael'thas und Vashj je eine Phiole gegeben hat. Holt zurück, was von den Phiolen noch übrig ist. Wir brauchen sie als Fokus, um ein Tor zu den Geschehnissen, seien sie aktuell oder vergangen, am Berg Hyjal zu öffnen. Das Ergebnis der Schlacht um den Berg Hyjal muss geschützt werden.", sourceObjective = "Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole im Echsenkessel und die Überreste von Kaels Phiole von Kael'thas Sonnenwanderer in der Festung der Stürme besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13433] = { id = 13433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
