quests[13501] = { id = 13501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[13502] = { id = 13502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Korb bekommen!", description = "Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.", sourceObjective = "Der Nobelgartenverkäufer möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13503] = { id = 13503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Korb bekommen!", description = "Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.", sourceObjective = "Der Nobelgartenhändler möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.", progress = "Habt Ihr die zehn Nobelgartenschokoladen?", completion = "Gut gemacht! Und hier, bitte... behaltet den Korb!\n\nUnd denkt dran, Ihr könnt jederzeit mit mehr Nobelgartenschokolade wiederkommen, um sie gegen weitere Gegenstände einzutauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13524] = { id = 13524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Silberwasser", description = "Ihr... Ihr seid keiner von ihnen? Schnell! Lasst mich raus!\n\nWir müssen schleunigst zur Ammertannhütte! Wenn Leutnant Dumont erst einmal herausfindet, wer diese Leute wirklich sind, dann wird diese Stadt in Schutt und Asche gelegt werden!", sourceObjective = "Öffnet den hölzernen Käfig und helft dem befreiten Späher der Allianz, aus Silberwasser zu entkommen. Meldet Euch bei Leutnant Dumont, sobald Ihr die Ammertannhütte erreicht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13538] = { id = 13538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage aus dem Süden", description = "Die drei Türme südlich des Tausendwinterflusses entziehen der Festung Energie!\n\nMacht den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm dem Erdboden gleich und erstattet mir dann Bericht. Denkt dran, nur Belagerungsmaschinen können einen Turm beschädigen, deshalb müsst Ihr sie gut vor der Horde beschützen!", sourceObjective = "Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Ahbramis in Tausendwinter zurück.", completion = "Ich habe die Explosion bis hier gehört! Gute Arbeit - wir haben schon damit begonnen, die Energie in das Relikt der Titanen umzuleiten, um eine Superaufladung für unsere eigenen Truppen zu ermöglichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13539] = { id = 13539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einstürzende Turmbauten", description = "Während die Allianz gegen unsere Türen hämmert, schaut ein wahrer Taktiker über das Offensichtliche hinaus.\n\n\"Greif ihn an, wo er unvorbereitet ist, erscheine, wo du nicht erwartest wirst.\"\n\n{name}, überquert den Tausendwinterfluss und macht einen der drei Türme im Süden dem Erdboden gleich. Unsere Hexenmeister berichten, dass die Türme Energie abziehen, die wir benutzen könnten, um unsere eigenen Truppen zu stärken.\n\nKehrt zu mir zurück, sobald Ihr einen Turm zerstört habt.", sourceObjective = "Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Kilrath in Tausendwinter zurück.", completion = "Und nun, um den Feind zu vernichten, muss der Zorn unserer Truppen geweckt werden. Um den Vorteil darin zu sehen, den Feind zu besiegen, müssen sie ihre Belohnungen erhalten. Ich hoffe, dass dies hier Euren Dienst an der Horde ausreichend entlohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13548] = { id = 13548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[13549] = { id = 13549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Männchen oder Weibchen?", description = "Ich bin daran interessiert, neben den Artefakten der Drakkari auch ein paar Tiere von Zul'Drak mit mir zurück nach Zandalar zu bringen. Männchen der Frostleoparden und Eispfotenbären habe ich schon - ich brauche aber Weibchen!\n\nZu dumm, dass mein Fallensteller in einem überaus unglücklichen Unfall ums Leben kam. Wäret Ihr vielleicht dazu bereit, für ihn einzuspringen?\n\nSchläfert die Leoparden und Bären mit diesem Blasrohr ein und vergewissert Euch, dass es auch Weibchen sein werden, die Ihr dann zu mir zurückbringt, wenn Ihr so nett sein würdet. Finden könnt Ihr sie an den Altären von Rhunok, Quetz'lun und Har'koa.", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr mit To'kinis Blasrohr Frostleoparden und Eispfotenbären einschläfert. Kehrt mit jeweils 3 Weibchen zu ihm zurück.", completion = "Wirklich sehr ausgezeichnete Exemplare, {name}! Sie werden mit Sicherheit für Neugierde und stundenlange Spekulationen unter meinen Kollegen zuhause sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13556] = { id = 13556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier für Dubra'Jin", description = "Wie geht's, Mann? Was meinst du, kannst du mir helfen? Bah'Kini braucht 'ne Menge Raptoreier, um sie Dubra'Jin zu opfern.\n\nWas denkst du denn, wieso uns die Drakkari noch nicht überrannt haben?! Ja weil Dubra'Jin uns hilft!\n\nDu musst für uns die Raptoreier sammeln - die sind hier in Gundrak bei den Bäumen. Manchmal tragen die Raptoren sie auch rum, damit sie warm bleiben.", sourceObjective = "Ha'wana in Dubra'Jin möchte, dass Ihr 12 Raptoreier von Gundrak sammelt.", progress = "Wer hätt gedacht, dass der große Dubra'Jin so viele Eier haben will? Was will der eigentlich mit denen?", completion = "Eins, zwei, drei... hehe, das wird reichen, Mann! Jetzt werden wir für 'ne ganze Weile sicher sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13559] = { id = 13559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodirs Tribut", progress = "Gewöhnlicher Tribut war nicht gut genug für den großen Hodir, als er unter den Frostriesen wandelte.\n\nEr mag zwar nicht mehr bei uns sein, doch wir haben die Tradition beibehalten, seiner Stärke und Weisheit Tribut zu zollen. Es täte Eurem Ruf sehr gut, wenn Ihr Euch an dieser Tradition beteiligen würdet, kleiner {class}.", completion = "Die Söhne Hodirs nehmen Euren Tribut an, kleines Wesen. Ihr schreitet voran auf Eurem Weg, Euren Wert als Verbündeter zu beweisen - auf mehr als eine Art." }
quests[13571] = { id = 13571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fletchers Fundbüro", sourceObjective = "Durch den Gestank nach etwas Abgestandenem und Ungewaschenem hindurch dringt Euch bekannter Geruch in die Nase! Es scheint, als wäre dieser einst so mächtige Abenteurer ganz verrückt nach Kungaloosh.\n\nAls Ihr durch die Gitterstäbe schaut, könnt Ihr gerade so eben das Rezept erkennen, das auf seinem Arm steht...", sourceObjectiveStatus = "unverified-source-field" }
quests[13592] = { id = 13592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Sir Marcus Barlow beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Selbst wenn wir für den Wettkampf trainieren, ist es gut, nicht zu vergessen, dass die Geißel noch immer da draußen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13593] = { id = 13593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Sturmwind", description = "Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation von Sturmwind beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Sturmwind ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Marschall Jacob Alerius, falls Ihr ein Recke von Sturmwind werden wollt.", completion = "Wir sind stolz, dass Ihr eingewilligt habt, mit uns zu trainieren und in unserem Namen anzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13600] = { id = 13600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierwaffe verloren und dabei brauche ich sie doch in der Partie heute Nachmittag.\n\nEiner der Barden hat mir erzählt, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Drak'Marsee in der nordöstlichen Drachenöde nahe der Grenze zu Zul'Drak und den Grizzlyhügeln.", sourceObjective = "Bringt Marschall Jacob Alerius beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "<Der Marschall nimmt die Klinge von Drak'Mar entgegen.>\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13603] = { id = 13603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Marschall Jacob Alerius beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13604] = { id = 13604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Datenscheibe des Archivums", description = "Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort \"ARCHIVUM\".\n\nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.", sourceObjective = "Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.", progress = "Die Konsole surrt vor Energie, als sich der runde Aufnahmebehälter öffnet.", completion = "Die Platinscheibe passt perfekt in die Konsole. Sie fängt an, sich zu drehen. Weiße Lichtstrahlen scheinen die darauf befindlichen Informationen abzutasten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13606] = { id = 13606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freyas Siegel", description = "Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.\n\nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.\n\nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.\n\nWas soll ich sagen, {name}, das ist eine ganz schöne Zwickmühle, in der wir da stecken.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Freyas Siegel, {name}? Habt Ihr es?", completion = "Verdammt gute Arbeit, {name}. Wir sind unserem Ziel, Azeroth zu retten, einen Schritt näher!", sourceObjectiveStatus = "unverified-source-field" }
quests[13607] = { id = 13607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das himmlische Planetarium", description = "Hört mal, <Kumpel/Mädel>! Das Schicksal von Azeroth steht hier auf dem Spiel.\n\nUnsere einzige Chance ist es, rechtzeitig das himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.\n\nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.", progress = "Habt Ihr ihn gefunden, {name}?", completion = "Es ist verschlossen? War ja klar!\n\nDann wollen wir doch mal sehen, was für Informationen wir aus diesem Müllhaufen rausholen können...", sourceObjectiveStatus = "unverified-source-field" }
quests[13609] = { id = 13609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodirs Siegel", description = "Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!\n\nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Habt Ihr das Siegel, {name}?", completion = "Ihr habt es geschafft! Ich weiß nicht wie, aber Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[13610] = { id = 13610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorims Siegel", description = "Thorim ist nicht er selbst, {name}. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.\n\nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.\n\nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!\n\nIhr müsst ihn zur Vernunft bringen und zwar schnell.\n\nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Nun, {name}? Habt Ihr's?", completion = "Ihr werdet wohl nie aufhören, mich zu beeindrucken, {name}.\n\nIhr und ich sollten mal ein Bierchen trinken gehen, nachdem wir mit all dem hier durch sind. Mein Wort drauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[13611] = { id = 13611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimirons Siegel", description = "Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.\n\nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, um sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Konntet Ihr das Siegel an Euch bringen, {name}?", completion = "Das muss man Euch wirklich lassen, {name}. Unsere Chancen stehen vielleicht nicht zum Besten, aber wenn Ihr mit anpackt fühle ich mich gleich viel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13614] = { id = 13614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Algalon", description = "Ihr habt es wirklich geschafft, {name}. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum himmlischen Planetarium erhaltet.\n\nIhr beeilt Euch besser, <Kumpel/Mädchen>. Die Zeit drängt.", sourceObjective = "Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.", progress = "Die gleißenden Lichter der Konsole scannen mehrmals die Glasoberfläche, gerade so, als ob eine Form von Datenübermittlung erwartet würde.", completion = "Verifizierungsprozess läuft.\n\nZugang zum himmlischen Planetarium gewährt. Bitte Schlüssel entnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13616] = { id = 13616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Marschall Jacob Alerius beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", progress = "Habt Ihr die Klinge errungen, nach der ich suche?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13622] = { id = 13622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Geschichten", description = "Die Stücke lassen sich zu einem eleganten Hammer zusammenfügen. Seine Bauweise erweckt den Eindruck, zumindest teilweise von titanischer Natur zu sein.\n\nWomöglich könnte man über die Konsole im Archivum mehr über dieses Artefakt erfahren.", sourceObjective = "Bringt die zerschmetterten Fragmente von Val'anyr zur Archivumkonsole im Archivum in Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13625] = { id = 13625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reitgrundlagen", description = "Die meisten Wettkämpfe des Turniers verlangen von den Wettstreitern, dass sie den Kampf auf einem Reittier beherrschen. Um Euch mit dem berittenen Kampf vertraut zu machen, haben wir überall im nördlichen Teil des Turnierplatzes Übungsattrappen aufgestellt.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und steigt auf das Streitross der Quel'dorei. Macht Euch mit den verfügbaren Taktiken vertraut und besiegt anschließend die drei verschiedenen Arten von Übungsattrappen.", sourceObjective = "Trefft ein Nahkampfziel 5 Mal mit der Fähigkeit \"Zustoßen\" und wendet die Fähigkeit \"Schildbrecher\" auf 2 ungeschützte Distanzziele sowie die Fähigkeit \"Anstürmen\" auf 2 ungeschützte Ansturmziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Gut gemacht, {name}. Für diejenigen, die den Kampf zu Boden gewohnt sind, ist es oft sehr schwer, den berittenen Kampf zu erlernen. Ich habe keine Zweifel daran, dass Ihr Euch mit entsprechender Übung weiterhin verbessern werdet - was weitaus mehr ist als das, was ich von manch anderen Kriegern behaupten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13627] = { id = 13627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie die Axt im Walde", description = "Kommt näher. Nein, nicht zu nah. Wir wollen doch keinen Grund für unnötige Verdächtigungen geben, nicht wahr?\n\nDiese Turnierhalle benötigt mehr Holz, als wir auf Lager haben, und die Kosten für einen Ferntransport von den Grizzlyhügeln werde ich auf keinen Fall zahlen. Im Westen des Kristallsangwaldes, in der Nähe des Großen Baumes, wachsen etliche junge Kristallsangeichen. Das wäre genau das Holz, das wir zum Bauen und als Gerüstmaterial bräuchten. Nehmt dieses Beil, schlagt einige Bäume und haut daraus ein paar Hölzer. Aber lasst Euch dabei bloß nicht erwischen!", sourceObjective = "Bringt 12 grob gehauene Bauhölzer zu Stumpi Sprengbolz beim Argentumturnierplatz.", progress = "Habt Ihr die \"Waren\", von denen wir gesprochen hatten?", completion = "Das ist exzellentes Bauholz und der Preis stimmt auch! Besser noch, diese angestaubten Typen vom Argentumkreuzzug werden's nie erfahren. Sie bekommen ihre heißgeliebte Turnierhalle und ich bekomme meinen Bonus für den schnellen Bauabschluß. Wenn das mal kein Gewinn für beide Seiten ist, dann weiß ich auch nicht mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[13629] = { id = 13629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'anyr, Hammer der Uralten Könige", description = "Die Archivumkonsole hat eine Möglichkeit angedeutet, wie die Fragmente von Val'anyr wieder zusammengefügt werden können: Ihr müsst die Fragmente ins Innere der körperlichen Form des Wesens namens Yogg-Saron bekommen.\n\nEs mag vielleicht aussichtslos klingen, doch Ihr denkt, dass ein Artefakt von solcher Macht das Risiko wert sein könnte.", sourceObjective = "Werft die zerschmetterten Teile von Val'anyr in Yogg-Sarons Schlund, während er den Zauber 'Ohrenbetäubendes Gebrüll' wirkt, und vernichtet ihn, um den neugeschmiedeten Hammer der Uralten Könige zu erhalten.\n\nDies kann nur auf dem Schwierigkeitsgrad \"Heroisch\" beendet werden und nur dann, wenn Ihr von maximal drei Wächtern von Ulduar unterstützt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13631] = { id = 13631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende gut, alles gut", description = "Wir sollten uns jetzt besser beeilen, {name}. Wir müssen den Antwortcode von Dalaran aus übermitteln.\n\nBringt ihn zu Rhonin. Ich treffe Euch dort.", sourceObjective = "Überbringt Rhonin in Dalaran den Antwortcode Alpha.", progress = "Seid Ihr soweit, {name}?", completion = "Ihr seid hier. Lasst uns hoffen, dass das hier klappt. Um unser aller willen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13633] = { id = 13633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Ritter von Westfall?", description = "Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.\n\nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.\n\nEr behauptet, der Cooperfamilie in Westfall zu entstammen. Würdet Ihr Euch aufmachen und den Wohnsitz der Familie in Mondbruch in Westfall aufsuchen? Vielleicht lässt sich dort ein Beweis für seine Geschichte finden.", sourceObjective = "Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.", progress = "Habt Ihr etwas über die Herkunft des Schwarzen Ritters herausfinden können?", completion = "Ihr meint also, an der Geschichte des Schwarzen Ritters wäre etwas faul? Sehr verdächtig. Ohne jede Ehre im besten Falle und im schlimmsten ein blutdürstiger Mörder. Trotzdem können wir ihn nicht zur Rede stellen, solange wir nicht wissen, dass er in die Morde verwickelt war.\n\nTut nichts, was seinen Verdacht erregen könnte, {name}. Diskretion wird uns von Nutzen sein, während wir unsere Nachforschungen vorantreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13634] = { id = 13634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Ritter von Silberwald?", description = "Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.\n\nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.\n\nEr behauptet, aus Valgans Feld im Silberwald zu stammen, einem kleinen Gehöft an der westlichen Küste des Lordameresees. Könntet Ihr dem Hof einen Besuch abstatten und mich wissen lassen, ob seine Geschichte der Wahrheit entspricht?", sourceObjective = "Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.", progress = "Habt Ihr etwas über die Herkunft des Schwarzen Ritters herausfinden können?", completion = "Ihr meint also, an der Geschichte des Schwarzen Ritters wäre etwas faul? Sehr verdächtig. Ohne jede Ehre im besten Falle und im schlimmsten ein blutdürstiger Mörder. Trotzdem können wir ihn nicht zur Rede stellen solange wir nicht wissen, dass er in die Morde verwickelt war.\n\nTut nichts, was seinen Verdacht erregen könnte, {name}. Diskretion wird uns von Nutzen sein, während wir unsere Nachforschungen vorantreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13641] = { id = 13641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seherkristall", description = "Jetzt, da wir wissen, dass der Schwarze Ritter nicht die Wahrheit spricht, müssen wir einen Weg finden, seine Verbindung zu den toten Rittern nachzuweisen.\n\nIch kenne einen Weg um die Wahrheit über ihren Tod aufzudecken, doch er benötigt ein seltenes Material. Wir müssen einen Seherkristall auftreiben, der nur bei den unbändigen Sehern gefunden werden kann, die sich in der Nähe der Nachtelfenruinen in den trostlosen Wäldern im Zentrum des Kristallsangwaldes versammeln. Findet einen dieser Seher, {name}, und bringt mir die Kristalle, die er bei sich trägt.", sourceObjective = "Bringt einen Seherkristall zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Habt Ihr einen Seherkristall finden können?", completion = "Der wird vollkommen genügen. Nun bleibt nur noch, ihn mit der Macht des Lichtes zu erfüllen, sodass er die Fähigkeit erhält, die unter Lügen verborgene Wahrheit zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13643] = { id = 13643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichten toter Männer", description = "Die Kristalle werden die Wahrheit darüber ans Tageslicht bringen, wie drei der Turnierteilnehmer gestorben sind. Bringt ihn zum Friedhof östlich des Turnierplatzes und benutzt ihn bei den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff.\n\nWenn diese Männer wirklich ermordet worden sind, dann müssen wir einen Weg finden, eine Verbindung zum Schwarzen Ritter herzustellen, bevor er wieder zuschlägt. Beobachtet genau, was der Kristall Euch zu sagen hat, {name}, denn wir müssen sicher sein, dass diese Todesfälle keine Zufälle gewesen sind.", sourceObjective = "Benutzt den Seherkristall an den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff, um herauszufinden, wie sie gestorben sind, und kehrt anschließend zu Kreuzfahrerin Rhydalla zurück.", progress = "Habt Ihr den Gräbern der erschlagenen Kämpfer einen Besuch abgestattet?", completion = "Ihr sagt also, dass Lorien Sonnenfeuer mit Gift getötet und Sir Wendell lebendig verbrannt wurde? Beides schreckliche Arten zu sterben. Nur Conall fand seinen Tod durch kalten Stahl und anhand Eurer Beschreibung war es die Tat eines Feiglings, die ihn ins Grab brachte, nicht ehrenhafter Kampf.\n\nAlle drei trainierten mit dem Schwarzen Ritter und sollten gegen ihn kämpfen. Das kann kein Zufall sein. Wir müssen einen Weg finden zu beweisen, dass es das Werk des Schwarzen Ritters gewesen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13649] = { id = 13649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justins spaßiger Test", description = "He da! Ihr seht aus, als könntet Ihr gut mit Bier umgehen. Doch wie gut könnt Ihr mit Eurem Trinkkrug umgehen? \n\nDie Dunkeleisenzwerge sind zurückgekommen, um unsere Feier zu ruinieren, und das nicht zu wenig. Sie mit Krügen zu bewerfen ist die beste Möglichkeit, sie aufzuhalten. Doch erst einmal wollen wir schauen, ob Ihr einen auf die alte A.L.K. hier werfen könnt.\n\nEs ist ganz leicht, nehmt einen Freibierkrug und trinkt. Geht dabei nur sicher, dass Ihr A.L.K. anseht. Sprecht mich wieder an, wenn Ihr sie fünfmal getroffen habt.", sourceObjective = "Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Boxey Bolzdreher.", sourceObjectiveStatus = "unverified-source-field" }
quests[13654] = { id = 13654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas ist mit dem Knappen", description = "Jeden Tag macht der Knappe des Schwarzen Ritters Maloric eine große Sache daraus, wie er mit der Axt auf seiner Schulter in Richtung Kristallsangwald aufbricht. Er will uns weismachen, er hacke Holz, nur kehrt er niemals mit mehr als nur ein paar Zweigen zurück.\n\nNormalerweise geht er in Richtung Ruinen südwestlich des Zwielichtspiegels. Er verbringt viel Zeit dort draußen, selbst für einen Knappen, der seinem Ritter gegenüber Pflichten hat.\n\nFindet einen Weg, ihn entweder abzulenken oder außer Gefecht zu setzen, und durchsucht ihn. Sollte er etwas im Schilde führen, dann werden wir es wissen.", sourceObjective = "Beschafft einen großen Oberschenkelknochen eines skelettierten Holzfällers und setzt damit Maloric außer Gefecht. Durchsucht ihn nach Beweisen und meldet Euch anschließend bei Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Habt Ihr den Knappen durchsucht und irgendwelche Anhaltspunkte gefunden?", completion = "<Kreuzfahrerin Rhydalla untersucht den Inhalt des Beutels mit angewidertem Gesicht.>\n\nEs ist alles da, {name}: das Gift, das Lorien tötete, eine Sammlung Messer, Fackeln und Öl. Niemand hier hat Grund dazu, diese Dinge zu besitzen, und kein Knappe würde dies ohne den Befehl seines ritterlichen Meisters tun. Wir haben unseren Mörder gefunden, {name}, doch für wen arbeitet er?", sourceObjectiveStatus = "unverified-source-field" }
quests[13662] = { id = 13662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anerkennung erlangen" }
quests[13663] = { id = 13663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befehle des Schwarzen Ritters", description = "Wir müssen herausfinden, wer den Schwarzen Ritter zum Turnier geschickt hat und was sich sein Meister daraus erhofft, die Konkurrenz zu töten.\n\nDie Kirin Tor haben in dieser Angelegenheit ihre Unterstützung angeboten und uns ein Werkzeug zur Verfügung gestellt, dass uns in unserer Suche helfen wird.\n\nBringt dieses verzauberte Zaumzeug zum Lager des Schwarzen Ritters am östlichen Rand des Turniergeländes und benutzt es, um Kontrolle über den Greifen des Schwarzen Ritters zu erhalten. Die Verzauberung des Zaumzeugs wird das Tier zwingen, Euch zum Wohnort seines Meisters zu bringen. Durchsucht ihn und bringt alles zurück, was Ihr finden könnt.", sourceObjective = "Erhaltet mithilfe des verzauberten Zaumzeugs Kontrolle über den Greifen des Schwarzen Ritters und reitet auf seinem Rücken zum Zielort. Beschafft Euch die gestohlene Einladung zum Turnier und die Befehle des Schwarzen Ritters, sobald Ihr dort angekommen seid, und bringt sie zurück zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Was habt Ihr herausgefunden?", completion = "<Kreuzfahrerin Rhydalla wird blass, als sie die Befehle liest.>\n\nDas kann nur eins bedeuten, {name}. Der Schwarze Ritter ist ein Anhänger des Kults der Verdammten und wurde von Arthas ausgesandt, um das Turnier zu stören!\n\nDer Schwarze Ritter hat sich als Furcht erregender Kämpfer entpuppt und Ihr werdet mindestens genauso gut sein müssen, um Ihm entgegenzutreten. Kehrt zu mir zurück, wenn Ihr Champion geworden seid, und wir werden einen Weg finden, für seine Niederlage zu sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13664] = { id = 13664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz des Schwarzen Ritters", description = "Wir müssen den finsteren Plänen des Schwarzen Ritters ein Ende setzen und unseren Widersachern zeigen, dass wir nicht untätig daneben stehen und zusehen, wie unsere Champions ermordet werden.\n\nEr wird mittlerweile annehmen, dass Ihm jemand auf den Fersen ist. Fordert ihn am helllichten Tage zum Kampf heraus, {name} - wenn er nicht ablehnen oder jemanden im Dunklen ermorden kann.\n\nNehmt mein Argentumstreitross für den Kampf. Es steht in den Stallungen, in der Nähe des Argentumpavillons.\n\nSprecht dann mit Knappe Cavin im Ring der Champions. Der Knappe wird den Schwarzen Ritter zum Kampf rufen und Ihr werdet ihn für seine Taten büßen lassen.", sourceObjective = "Besiegt den Schwarzen Ritter und sprecht anschließend mit Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Ist es vollbracht?", completion = "Mit dem Tod des Schwarzen Ritters kann das Turnier einmal mehr seinen Nutzen erfüllen. Die Champions der Horde und Allianz können ihre Waffenfertigkeiten demonstrieren und für den Tag trainieren, an dem Arthas und seine Diener keine Bedrohung mehr für uns darstellen werden.\n\nIhr habt den Dank des Argentumkreuzzugs, {name}, und all derer, die unserem Ruf gefolgt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13665] = { id = 13665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Sturmwind lieben ihre Ritter über alles und freuen sich darauf, uns gewinnen zu sehen. Damit das auch geschieht, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf das Streitross aus Sturmwind, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Hauptmann Joseph Holley beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr Sturmwind stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13666] = { id = 13666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Einige der Champions glauben, dass eine uralte Waffe aus Nordend ihnen auf dem Turnier Glück bringen wird. Nun habe ich meine Zustimmung gegeben, ihnen bei der Suche nach diesen Waffen zu helfen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Arkanist Taelis beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "An diesen alten Geschichten ist also etwas Wahres dran? Wie es scheint, haben sie in Bezug auf die Qualität der Klinge nicht gelogen. Gut gemacht, {name}. Der Champion, der sie trägt, wird in der Tat ein Glückspilz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13667] = { id = 13667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Argentumturnier", description = "Wir haben Euch hierher eingeladen, damit Ihr Euer Können und Euren Wagemut mit anderen messt, die sich der Geißel tapfer widersetzt haben. Wir hatten viele Meinungsverschiedenheiten, doch nun ist die Zeit gekommen, dass sich Helden aller Lager im Schwertkampf gegenseitig auf die Probe stellen, um sich auf die Begegnung mit unserem gemeinsamen Feind vorzubereiten.\n\nArkanist Taelis ist der Repräsentant des Silberbunds in diesem Turnier. Er wird Euch in die Schriftrollen eintragen und Euer Training beginnen lassen. Ihr findet ihn im großen Zelt der Allianz im nordöstlichen Teil des Geländes.", sourceObjective = "Sprecht mit Arkanist Taelis beim Argentumturnierplatz, um Euch für das Turnier anzumelden.", completion = "Ich habe Euren Namen in die Listen aufgenommen, {name}. Als Streiter werdet Ihr mit anderen zusammen üben, die im Turnier kämpfen möchten, und Eure Fähigkeiten im berittenen Kampf verfeinern. Sobald Ihr Euch bewiesen habt, wird es Euch erlaubt sein, im Auftrag Eurer Hauptstadt dem niedrigsten Rang des Wettkampfes beizutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13668] = { id = 13668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Argentumturnier", description = "Wir haben Euch hierher eingeladen, damit Ihr Euer Können und Euren Wagemut mit anderen messt, die sich der Geißel tapfer widersetzt haben. Wir hatten viele Meinungsverschiedenheiten, doch nun ist die Zeit gekommen, dass sich Helden aller Lager im Schwertkampf gegenseitig auf die Probe stellen, um sich auf die Begegnung mit unserem gemeinsamen Feind vorzubereiten.\n\nMagister Edien Sonnental ist der Repräsentant der Sonnenhäscher in diesem Turnier. Er wird Euch in die Schriftrollen eintragen und Euer Training beginnen lassen. Ihr findet ihn im großen Zelt der Horde im südöstlichen Teil des Geländes.", sourceObjective = "Sprecht mit Magister Edien Sonnental beim Argentumturnierplatz, um Euch für das Turnier anzumelden.", completion = "Ich habe Euren Namen in die Listen aufgenommen, {name}. Als Streiter werdet Ihr mit anderen zusammen üben, die im Turnier kämpfen möchten, und Eure Fähigkeiten im berittenen Kampf verfeinern. Sobald Ihr Euch bewiesen habt, wird es Euch erlaubt sein, im Auftrag Eurer Hauptstadt dem niedrigsten Rang des Wettkampfes beizutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13669] = { id = 13669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Unsere Champions haben Gefallen an uralten Waffen gefunden, die hier in Nordend hergestellt wurden.\n\nDie Barden erzählen Geschichten von Reisenden, die einer einsamen Maid Winterhyazinthen anbieten und dafür Geschenke bekommen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Sammelt die Blumen und bringt sie zum Lampenkreis auf dem Drak'Marsee im Nordosten der Drachenöde in der Nähe von Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt die Klinge von Drak'Mar zu Arkanist Taelis beim Argentumturnierplatz.", progress = "Stimmen die Geschichten der wandernden Barden? Habt Ihr eine Klinge mitgebracht?", completion = "Es besteht kein Zweifel daran, dass dies eine Klinge von außerordentlicher Qualität und Balance ist. Nun verstehe ich, weshalb diese Waffen unter den Champions der Allianz so begehrt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13670] = { id = 13670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Der Knappe des Großchampions von Eisenschmiede hat mir eine interessante Geschichte erzählt.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Arkanist Taelis beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so ausgezeichnet, wie der Knappe meinte, doch woher wusste er von ihr? Das macht nichts - sie wird ihrem neuen Besitzer gute Dienste leisten. Vielleicht ist es nur gerecht, dass der Großchampion von Eisenschmiede der einzige sein wird, der sie trägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13671] = { id = 13671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübung", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Während Ihr auf dem Weg seid, den berittenen Kampf zu beherrschen, vergesst nicht, die Fähigkeiten zu trainieren, die Euch all die Jahre über gut gedient haben. Zeigt uns, dass Ihr der Geißel mit Ehre und Tapferkeit begegnen könnt, und Ihr werdet Euch das Recht verdienen, auf diesem Turnier anzutreten.\n\nReist nach Eiskrone und tötet jeden Diener der Geißel, den Ihr dort seht. Haltet Euch jedoch vom Bombardement fern - man würde Euch überwältigen.", sourceObjective = "Avareth Flinkstoß beim Argentumturnierplatz möchte, dass Ihr 8 Diener der Geißel von Eiskrone tötet. Dazu zählen alle Diener der Geißel im Bereich von Eiskrone, abgesehen vom Bombardement.", progress = "Habt Ihr Euch im Kampf gegen die Geißel erprobt?", completion = "Ihr habt Euch als fähiger Kämpfer erwiesen, {name}, und Ihr werdet dem Rest der Streiter ein Beispiel sein, die da lautstark fordern, im Auftrag der Allianz anzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13672] = { id = 13672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herausforderung gewachsen", description = "Wenn Ihr die Fähigkeiten des Streiters gemeistert habt, könnt Ihr Euch dazu entscheiden, die Herausforderung des Streiters anzunehmen. Sie wird Euer Können im berittenen Kampf auf die Probe stellen und messen, ob Ihr bereit seid, ein Recke zu werden oder nicht. Solltet Ihr bestehen, werdet Ihr der Delegation Eurer Hauptstadt als Recke beitreten können.\n\nKehrt zu mir zurück, wenn Ihr für die Herausforderung bereit seid.", sourceObjective = "Überreicht Arkanist Taelis beim Argentumturnierplatz 15 Siegel des Streiters, um zu zeigen, dass Ihr bereit seid, Euch der Herausforderung des Streiter zu unterziehen.", progress = "Wollt Ihr Euch der Herausforderung des Streiters stellen?", completion = "Sehr gut, ich werde die Vorbereitungen treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13673] = { id = 13673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Einige der Champions glauben, dass eine uralte Waffe aus Nordend ihnen auf dem Turnier Glück bringen wird. Nun habe ich meine Zustimmung gegeben, ihnen bei der Suche nach diesen Waffen zu helfen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Magister Edien Sonnental beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "An diesen alten Geschichten ist also etwas Wahres dran? Wie es scheint, haben sie in Bezug auf die Qualität der Klinge nicht gelogen. Gut gemacht, {name}. Der Champion, der sie trägt, wird in der Tat ein Glückspilz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13674] = { id = 13674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Unsere Champions haben Gefallen an uralten Waffen gefunden, die hier in Nordend hergestellt werden.\n\nDie Barden erzählen Geschichten von Reisenden, die einer einsamen Maid Winterhyazinthen anbieten und dafür Geschenke bekommen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Sammelt die Blumen und bringt sie zum Lampenkreis auf dem Drak'Marsee im Nordosten der Drachenöde in der Nähe von Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt die Klinge von Drak'Mar zu Magister Edien Sonnental beim Argentumturnierplatz.", progress = "Stimmen die Geschichten der wandernden Barden? Habt Ihr eine Klinge mitgebracht?", completion = "Es besteht kein Zweifel daran, dass dies eine Klinge von außerordentlicher Qualität und Balance ist. Nun verstehe ich, weshalb diese Waffen unter den Champions der Allianz so begehrt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13675] = { id = 13675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Einer der Recken von Orgrimmar hat mir eine interessante Geschichte erzählt.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Magister Edien Sonnental beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so ausgezeichnet, wie der Recke meinte, doch woher wusste er von ihr? Das macht nichts - sie wird ihrem neuen Besitzer gute Dienste leisten. Vielleicht ist es nur gerecht, dass der Großchampion von Orgrimmar der einzige sein wird, der sie trägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13676] = { id = 13676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübung", description = "Das Turnier ist eine Gelegenheit, Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Vergesst nicht, auf Eurem Weg zur Beherrschung des berittenen Kampfes auch die Fähigkeiten zu trainieren, die Euch all die Jahre über gut gedient haben. Zeigt uns, dass Ihr der Geißel mit Ehre und Tapferkeit begegnen könnt, und Ihr werdet Euch das Recht verdienen, auf diesem Turnier anzutreten.\n\nReist nach Eiskrone und tötet jeden Diener der Geißel, den Ihr dort seht.", sourceObjective = "Amariel Sonnenschwur beim Argentumturnierplatz möchte, dass Ihr 8 Diener der Geißel von Eiskrone tötet. Dazu zählen alle Diener der Geißel im Bereich von Eiskrone, abgesehen vom Bombardement.", progress = "Habt Ihr Euch im Kampf gegen die Geißel erprobt?", completion = "Ihr habt Euch als fähiger Kämpfer erwiesen, {name}, und Ihr werdet dem Rest der Streiter ein Beispiel sein, die da lautstark fordern, im Auftrag der Horde anzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13677] = { id = 13677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reitgrundlagen", description = "Die meisten Wettkämpfe des Turniers erfordern von den Wettstreitern, dass sie den Kampf auf einem Reittier beherrschen. Um Euch mit dem berittenen Kampf vertraut zu machen, haben wir überall im nördlichen Teil des Turnierplatzes Übungsattrappen aufgestellt.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und steigt auf den Falkenschreiter der Sonnenhäscher. Macht Euch mit ihm vertraut und besiegt anschließend die drei verschiedenen Arten von Übungsattrappen.", sourceObjective = "Trefft ein Nahkampfziel 5 Mal mit der Fähigkeit \"Zustoßen\" und wendet die Fähigkeit \"Schildbrecher\" auf 2 ungeschützte Distanzziele sowie die Fähigkeit \"Anstürmen\" auf 2 ungeschützte Ansturmziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", completion = "Gut gemacht, {name}. Für diejenigen, die den Kampf zu Boden gewohnt sind, ist es oft sehr schwer, den berittenen Kampf zu erlernen. Ich habe keine Zweifel daran, dass Ihr Euch mit entsprechender Übung weiterhin verbessern werdet - was weitaus mehr ist als das, was ich von manch anderen Kriegern behaupten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13678] = { id = 13678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herausforderung gewachsen", description = "Wenn Ihr die Fähigkeiten des Streiters gemeistert habt, könnt Ihr Euch dazu entscheiden, die Herausforderung des Streiters anzunehmen. Sie wird Euer Können im berittenen Kampf auf die Probe stellen und messen, ob Ihr bereit seid, ein Recke zu werden oder nicht. Solltet Ihr bestehen, werdet Ihr der Delegation Eurer Hauptstadt als Recke beitreten können.\n\nKehrt wieder zu mir zurück, wenn Ihr bereit seid, die Herausforderung anzutreten.", sourceObjective = "Überreicht Magister Edien Sonnental beim Argentumturnierplatz 15 Siegel des Streiters, um zu zeigen, dass Ihr bereit seid, Euch der Herausforderung des Streiters zu unterziehen.", progress = "Wollt Ihr Euch der Herausforderung des Streiters stellen?", completion = "Sehr gut, ich werde die Vorbereitungen treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13679] = { id = 13679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Streiters", description = "Ihr habt hart trainiert, <Streiter/Streiters> {name}, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen geschickten Gegner auf die Probe zu stellen.\n\nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf das Streitross der Quel'dorei, das dort untergebracht ist.\n\nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr Knappe David vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.\n\nViel Glück, {name}. Möget Ihr stets sicher im Sattel sitzen und Eure Pfeile ins Schwarze treffen.", sourceObjective = "Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Arkanist Taelist beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Meine gebührenden Glückwünsche, {name}. Ihr habt Euren Herausforderer geschlagen und Euch das Recht verdient, zum Recken aufzusteigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13680] = { id = 13680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Streiters", description = "Ihr habt hart trainiert, <Streiter/Streiterin> {name}, und nun ist die Zeit gekommen, Euer Können im berittenen Kampf gegen einen erfahrenen Gegner auf die Probe zu stellen.\n\nNehmt Eure Lanze, geht dann zu den angebundenen Reittieren außerhalb des Pavillons und steigt auf den Falkenschreiter der Sonnenhäscher.\n\nIm Ring der Streiter auf der nördlichen Seite des Turnierplatzes werdet Ihr ein Menschenkind, einen Knappen namens David, vorfinden. Er wird sich vergewissern, dass Ihr bereit seid zu kämpfen, und Euren Widersacher herbeirufen.\n\nViel Glück, {name}. Möget Ihr sicher im Sattel sitzen und Euer Pferd gleichmäßig reiten.", sourceObjective = "Sprecht mit Knappe David und ruft Euren Widersacher herbei. Kehrt zu Magister Edien Sonnental beim Argentumturnierplatz zurück, sobald Ihr den Argentumrecken besiegt habt.", completion = "Meine gebührenden Glückwünsche, {name}. Ihr habt Euren Herausforderer geschlagen und Euch das Recht verdient, zum Recken aufzusteigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13681] = { id = 13681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Block so der Splitter", description = "Stein für diesen Job zu besorgen war der reinste Alptraum, das kann ich Euch sagen! Es gibt in den Ruinen sichere Orte, an denen es tonnenweise Stein zu finden gibt, doch diese selbstgerechten Paladine wollen einfach nicht zugreifen. Hat was mit unbezahlbaren Artefakten zu tun, oder so was.\n\nWie dem auch sei: Darüber zu jammern wird auch nicht helfen, diesen Ort aufzubauen. In den Fußmarschen und der Bibliothek des Erfinders in den Sturmgipfeln gibt es eine ganze Reihe Titanenruinen. Nehmt meinen, ähm, 'Meißel' mit und seht, ob Ihr diese riesigen Blöcke nicht in brauchbare Stücke zerhauen könnt.", sourceObjective = "Bringt 15 kleine Steinblöcke zu Stümpi Sprengbolz beim Argentumturnierplatz.", progress = "Habt Ihr die Steinblöcke dabei?", completion = "Die sollten reichen. Sagt den Kreuzfahrern bloß nicht, woher Ihr sie habt. Ich bin mir sicher, dass sie sich darüber aufregen würden. Aber hey, es ist ja nicht so, als wären die Titanen für sie zurückgekommen. Wenn's nach mir geht, kann man sie sich einfach nehmen. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13682] = { id = 13682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.\n\nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr und Eure Verbündeten habt das Turnier vor einem vernichtenden Angriff bewahrt. Unsere Himmelsklauenreiter mögen zwar tapfer sein, haben jedoch alle Hände voll damit zu tun, den Frieden auf dem Turnierplatz zu wahren, und sie hätten Mühe damit, den Luftraum gegen die Angriffe des Kults zu verteidigen. Euch gehört der Dank des Argentumkreuzzugs und all derjenigen, die sich hier versammelt haben, um am Wettkampf teilzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13684] = { id = 13684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Sturmwind", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Sturmwind anzutreten, {name}. Nun solltet Ihr mit Marschall Jacob Alerius sprechen, der Sturmwinds Wettkämpfer anführt. Als Großchampion von Sturmwind wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Marschall Jacob Alerius beim Argentumturnierplatz, um ein Recke von Sturmwind zu werden.", completion = "Na dann willkommen an Bord, Recke {name}. Die Delegation von Sturmwind ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13685] = { id = 13685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Eisenschmiede", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Eisenschmiede anzutreten, {name}. Nun solltet Ihr mit Lana Starkhammer sprechen, die die Wettkämpfer von Eisenschmiede anführt. Als Großchampion der Stadt wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Lana Starkhammer beim Argentumturnierplatz, um ein Recke von Eisenschmiede zu werden.", completion = "Gut, Euch kennenzulernen, Recke. Eisenschmiede braucht Wettkämpfer wie Euch, um auf dem Turnier zu bestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13688] = { id = 13688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Gnomeregan", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Gnomeregan anzutreten, {name}. Nun solltet Ihr mit Ambrose Bolzenfunk sprechen, der die Wettkämpfer von Gnomeregan anführt. Als Großchampion der Gnome wird er Euch in ihrem Namen für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Ambrose Bolzenfunk beim Argentumturnierplatz, um ein Recke von Gnomeregan zu werden.", completion = "Na dann willkommen an Bord, Recke {name}. Die Delegation von Gnomeregan ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13689] = { id = 13689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Darnassus", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Darnassus anzutreten, {name}. Nun solltet Ihr mit Jaelyne Abendlied sprechen, die die Wettkämpfer von Darnassus anführt. Als Großchampion der Nachtelfen wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Jaelyne Abendlied beim Argentumturnierplatz, um ein Recke von Darnassus zu werden.", completion = "Willkommen zur Turniersdelegation von Darnassus, {name}. Es wird eine Freude sein, an Eurer Seite zu trainieren und am Wettkampf teilzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13690] = { id = 13690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke der Exodar", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner der Exodar anzutreten, {name}. Nun solltet Ihr Euch Kolosos vorstellen, dem Leiter der Delegation der Exodar. Als Großchampion der Draenei wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Kolosos beim Argentumturnierplatz, um ein Recke der Exodar zu werden.", completion = "Na dann willkommen an Bord, Recke {name}. Die Delegation der Exodar ist stolz, Euch unter seinen Mitgliedern zählen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13691] = { id = 13691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Orgrimmar", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Orgrimmar anzutreten, {name}. Nun solltet Ihr mit Mokra dem Schädelberster sprechen, der Orgrimmars Wettkämpfer anführt. Als Großchampion von Orgrimmar wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Mokra dem Schädelberster beim Argentumturnierplatz, um ein Recke von Orgrimmar zu werden.", completion = "Ihr wollt also für Orgrimmar antreten? Nur, weil Ihr ein paar Attrappen verhauen habt, heißt das noch lange nicht, dass Ihr auch gewinnen werdet. Doch von nun an werdet Ihr mit den Besten zusammen trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13692] = { id = 13692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert und die See", description = "Mein Schwert ist auf See verloren gegangen. Holt es herauf und bringt es zurück!", sourceObjective = "Der alte Barlo im Kristallsangwald möchte, dass Ihr ihm das Schwert der Ritterwürde bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13693] = { id = 13693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Sen'jin", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Sen'jin anzutreten, {name}. Nun solltet Ihr mit Zul'tore sprechen, der die Krieger von Sen'jin anführt. Als Großchampion der Trolle wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Zul'tore beim Argentumturnierplatz, um ein Recke von Sen'jin zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13694] = { id = 13694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Donnerfels", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Donnerfels anzutreten, {name}. Nun solltet Ihr mit Runok Wildmähne sprechen, der Donnerfels' Wettkämpfer anführt. Als Großchampion von Donnerfels wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Runok Wildmähne beim Argentumturnierplatz, um ein Recke von Donnerfels zu werden.", completion = "Im Namen von Donnerfels und seinen Kriegern heiße ich Euch willkommen, {name}. Kämpft unter unserem Banner stets mit Ehre und Tapferkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13695] = { id = 13695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Unterstadt", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Unterstadt anzutreten, {name}. Nun solltet Ihr mit Todespirscher Visceri sprechen, der Unterstadts Wettkämpfer anführt. Als Großchampion wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Todespirscher Visceri beim Argentumturnierplatz, um ein Recke von Unterstadt zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13696] = { id = 13696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Recke von Silbermond", description = "Ihr habt Euch als würdig erwiesen, unter dem Banner von Silbermond anzutreten, {name}. Nun solltet Ihr mit Eressea Morgensänger sprechen, die Silbermonds Wettkämpfer anführt. Als Großchampion von Silbermond wird sie Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.\n\nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, {name}, und ich wünsche Euch Glück im bevorstehenden Wettkampf.", sourceObjective = "Sprecht mit Eressea Morgensänger beim Argentumturnierplatz, um ein Recke von Silbermond zu werden.", completion = "Ihr wollt also für Silbermond antreten? Nun gut. Ich werde Euch in die Namensliste aufnehmen und Ihr könnt sofort damit anfangen, mit den anderen Recken zusammenzuarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13697] = { id = 13697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Mokra dem Schädelberster beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13699] = { id = 13699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen Sturmwinds beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Marschall Jacob Alerius beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen Sturmwinds auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13702] = { id = 13702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
